(window.STORIES=window.STORIES||[]).push(...[{"n": 200, "l": "الجزء 174 | احداث السنه الثامنه من الهجرة | سبب الهزيمه في حنين ثم النصر", "u": "https://www.facebook.com/groups/710210019782034/permalink/836545483815153/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وأربعة_وسبعون\n#أحداث_السنة_الثامنة_من_الهجرة\n#سبب_الهزيمة_في_حنين_ثم_النصر\nاتكلمنا المرة إللي فاتت عن دخول المسلمين وادي حنين بعد ما قعدوا أربعة أيام في الطريق، وشوفنا إزاي دخلوا أرض المعركة على طول بدون تأَنّي أو تفكير،\nوكنتيجة للخطأ العسكري ده كان جيش هوازن مجهز كمائن في الوادي فالكمائن دي هجمت على المسلمين بالسهام والحِراب،\nوبسبب إللي حصل ده بدأ جيش المسلمين يهرب من أرض المعركة ومتبقاش مع رسول الله ﷺ غير عشرة فقط، \nطبعا في رويات تانية عن العدد إللي ثبت مع رسول الله ﷺ، يعني في رواية بتقول إنهم كانوا أربعة وفي رواية إنهم كانوا مائة،\nلكن أصح رواية هي الرواية إللي فيها العشرة،\nاحنا بقى عايزين نعرف ليه حصل كل ده\nالمسلمين وهمّ خارجين في الطريق لحنين، شافوا إن عددهم اثنا عشر ألفا و ده أول أكبر عدد للمسلمين،\nفقال بعض المسلمين من الطّلقاء:\nلن نُغلب اليوم من قِلة\nيعني احنا عددنا كتير ومش هنتغلب النهاردة،\nوطبعا الكلمة دي كارثة\nلأنه كده حصل عندهم عُجب، والمقصود بالعُجب هنا هو الاعتماد على الأسباب ونسيان رب الأسباب، بمعني إني أظن إن أنا إللي عملت كذا وكذا والفضل يرجع لي أنا ولمجهودي مش لربنا،\nواحنا لو سألنا حد من الصحابة أو الصالحين سؤال مباشر وقلنا:\nهل النصر من عندك أم من عند الله؟ \nمفيش أي شك إن الكل هيجاوب بدون تردد : طبعا النصر من عند الله\nلكن شعور الإعجاب بالنفس والغرور بيبقى شعور خفي بيتسلل للنفس براحة ومن غير ما الواحد ياخد باله وميحسش بيه إلا بعد ما بيكبر جواه وتحصل له الكوارث بسببه\nومشكلة الأمراض القلبية دي بقى زي العُجب والكبر وحب الدنيا والحسد وغيرها إنها أمراض مُعدية\nيعني لو ظهرت في مجموعة بسيطة ومتعالجتش كويس هتنتشر زي الوباء،\nإللي أعجبتهم الكثرة كانوا مجموعة من المسلمين من الطلقاء إللي لسه مسلمين جديد؛ لأن الصحابة جايين من المدينة في عشرة آلاف ومحصلهمش العُجب، فمش الألفين الزيادة دول همّ يعني إللي هيفرقوا\nفمع إن مجموعة صغيرة هي إللي قالت الكلمة دي، إلا إن باقي الجيش اتأثر بيها ودخل العجب في قلوبهم من غير ما يحسّوا،\nعشان كده ييجي دور الأمر بالمعروف والنهي عن المنكر إللي كان واضح إنه متحققش هنا في الغزوة دي على أكمل وجه بين المسلمين، وإلا كان المفروض إن الصحابة يقولوا لبعض لأ، احنا مش بننتصر بالعدد ولا بالسلاح ده ربنا هو إللي بينصرنا،\nلكن واضح إن محدش قال كده\nودي نتيجة خروج ضِعاف الإيمان في وسط الجيش المؤمن\nولو تفتكروا في غزوة أحد لما المنافقين انسحبوا قبل بداية المعركة إزاي انسحب بسببهم بعض المؤمنين الصادقين،\nوربنا بعدها قال عنهم :\n\"لَوْ خَرَجُوا فِيكُمْ مَا زَادُوكُمْ إِلَّا خَبَالًا وَلَأَوْضَعُوا خِلالَكُمْ\"\nهمّ الطلقاء مكنوش منافقين ولكنهم كانوا حديثي عهد بجاهلية، لسه مسلمين من أقل من شهر، ولم يمروا بتجارب إيمانية كافية عشان قلوبهم تثبت على الإيمان زي باقي الصحابة،\nلكن رسول الله ﷺ كان مضطر ياخدهم معاه لأنه خاف لو تركهم في مكة ينقلبوا ويرجعوا للكفر مرة تانية وينفصلوا بمكة عن الدولة الإسلامية زي ما قلنا قبل كده،\nففي الظروف العادية الأفضل ألا يخرج للقتال متذبذب الإيمان؛ لأن للأسف في مؤمنين صادقين هيسمعوا لضعفاء الإيمان دول ويتأثروا بيهم زي ما ربنا قال:\n\"وَفِيكُمْ سَمَّاعُونَ لَهُمْ\"\nوهو ده إللي حصل، لما اتقالت كلمة : لن نُغلب اليوم من قِلة،\nانتشرت الكلمة في جيش المسلمين واتأثروا بيها،\nطيب إيه بقى مشكلة العُجب هنا\nيعني الجملة إللي قالوها ظاهرها صحيح، اثنا عشر ألف مقاتل مش عدد صغير،\nوحتى في حديث عن رسول الله ﷺ بيقول:\n\" لا يُغلب اثنا عشر ألفاً من قلة\"\n《الحديث ده \nعلى خلاف بين العلماء، علماء قالوا صحيح وعلماء قالوا ضعيف》\nفمعنى الحديث إن اثنا عشر ألف مقاتل مش هيُغلبوا بسبب قلة عددهم، لكن ممكن يُهزموا لسبب تاني زي أسباب مادية أو أسباب قلبية،\nيعني يكون عندنا اثنا عشر ألف مقاتل لكن معندهمش إعداد عسكري، أو معندهمش قوة سلاح، \nأو عندهم خلل في الخطة، أو عدم مهارة في القيادة.. أو غيرها من الأمور المادية،\nلكن جيش المسلمين إللي كان خارج لحنين كان على أعلى مستوى من التجهيزات، فحصل له الهزيمة بسبب العُجب إللي دخل قلوبهم\n◇طب رسول الله ﷺ لما سمع الكلمة وعرف خطورتها ليه متكلمش ونبههم\nرسول الله ﷺ لما سمع الكلمة دي حس إن في مشكلة هتحصل، وحزن لما سمعها،\nوعرف إن العُجب دخل في قلوب المسلمين، فمهما هيقول أي كلام مش هيأثر لازم حاجة شديدة تحصل تخليهم ينتبهوا للمرض الخطير ده، \nفربنا لم يُرِد لرسول  الله ﷺ إنه يقول كلمة أو خطبة تُشعر المسلمين بمدى المأساة إللي هتحصل لهم إذا أُصيبوا بداء العجب؛\nلأنهم لو خرجوا بكلمة أو خطبة من غير ما يحصل لهم أمر شديد، المرض ده هيتسلل أكثر وأكثر إلى قلوبهم،\nفكان لا بد من مصيبة تهز المسلمين وتوضح لهم الرؤية وتوضح لهم الصورة تمام الوضوح\nفوقعوا بقى في أخطاء مكنوش بيقعوا فيها في الظروف العادية، واحنا شوفنا عبقرية خالد بن الوليد وعمرو بن العاص في قيادة الجيوش قبل كده في مؤتة وفي ذات السلاسل، \nفمصيبة زي كده هتسيب أثر تربوي كبير جدا أعظم من أثر ألف خطبة ممكن الواحد يسمعها،\nفالوحي لم ينزل عشان ينبه المسلمون للخطر إللي همّ داخلين عليه؛ عشان يذوقوا النتيجة المُرّة لمرضهم الخطير فينتبهوا بعد كده وميقعوش في الخطأ ده، والموقف ده كده أبلغ في تربية المسلمين\nورسول الله ﷺ متكلمش لكنه اكتفى إنه يدعي بعد صلاة الصبح طول أيام حنين، \nحتى الصحابة استغربوا لأنهم شافوا رسول الله ﷺ بيعمل حاجة مكنش بيعملها قبل كده فسألوه:\nيا رسول الله! إنا نراكَ تفعل شيئا لم تكن تفعَلُه، فما هذا الذي تحرك شفتيك؟\nفقال لهم رسول الله ﷺ:\nإن نبياً فيمن كان قبلكم أعجبته كثرة أمته فقال:\nلن يَرُوم هؤلاء شيء، فأوحى الله إليه أن خيّر أمتك في إحدى ثلاث:\nإما أن نُسلط عليهم عدوا من غيرهم فيَستبِيحَهم، أو الجوع، وإما أن أُرسل عليهم الموت.\nفشاوَرَهم نبيهم فقالوا له:\nأما العدو فلا طاقةَ لنا بهم، وأما الجوع فلا صبر لنا عليه، ولكن الموت، فأُرسل عليهم الموت فمات منهم في ثلاثة أيام سبعون ألفا.\nقال رسول الله ﷺ : فأنا أقول الآن:\n \"اللهم بك أُحاوِل، وبك أُصاوِل، وبك أُقِاتل\".\nيعني رسول الله ﷺ بيقول لهم إن كان في نبي من الأنبياء السابقين أعجبه كثرة أعداد أمته فقال مفيش حد هيقدر يقف قصادهم ولا يغلبهم،\nفربنا أوحى له إنه يخيّر أُمته بثلاثة اختيارات إما إنه يسلط عليهم عدو يقاتلهم، أو يبتليهم بالجوع أو الموت،\nفلما شاورهم اختاروا الموت لأنه أهون من لقاء العدو ومن الجوع، فمات منهم في ثلاثة أيام سبعون ألف،\nفرسول الله ﷺ لما شاف كثرة أعداد المسلمين افتكر النبي ده وبقى يدعي ربنا ويقول إنه بيدفع الاعدأء ويقاتلهم ويغلبهم بحول الله وقوته مش بكثرة عدد ولا بكثرة سلاح،\nوأنا بقولكم الحديث ده عشان أعرفكم إن رسول الله ﷺ لم يدخل في قلبه العجب،\nلأن في رواية في كتاب 《السيرة النبوية لابن هشام》 بتقول إن رسول الله ﷺ نفسه هو إللي قال: لن نُغلب اليوم من قِلة، والرواية دي لا تثبت عن رسول الله ﷺ،\nومستحيل أصلا رسول الله ﷺ يقول كلمة زي دي وهو من عادته الخضوع والتواضع لله، والتوكل عليه في كل شيء\nوفي رواية تانية برده بتقول إن أبا بكر الصديق هو كمان قال كده،لكن برده الرواية دي لا تصح،\nفاللي يهمنا من الموضوع إن بعض المسلمين وقع العجب في قلوبهم وصرّحوا بيه وتأثر به باقي الجيش، أما ورسول الله ﷺ مكنش من إللي عجبه الكثرة دي.\n☆ملحوظة بس عشان محدش يفهم غلط\nالإعجاب بالنفس مش هو الثقة بالنفس، \nثقة الإنسان بنفسه و بقدراته وبخبرته حاجة كويسة ومطلوبة، والجيش لا ينتصر ولا ينجح لو معندش ثقة بالنفس،\nلكن لا يجب أن تزيد الثقة بالنفس حتى تصل إلى درجة التوكل على النفس وإنها تقدر تعمل أي حاجة بنفسها من غير الاستعانة والتوكل على الله، \nوإلا فهنا الثقة اتحولت للعجب الذموم،\nوالفرق بين الثقة بالنفس والإعجاب بالنفس شعرة، والمُوَفق من وفقه الله فعلا\nفالكلمة إللي اتقالت من بعض المسلمين في الجيش مكنتش ثقة بالنفس ولكنها كانت إعجاب بالنفس، وإللي يأكد لنا إنها فعلا كانت إعجاب بالنفس هو كلام رب العالمين لما قال لهم:\n\"وَيَوْمَ حُنَيْنٍ إِذْ أَعْجَبَتْكُمْ كَثْرَتُكُمْ\"\nفلما دخل مرض العُجب في قلوبهم كانت النتيجة إنهم اتجهوا إلى حُنين وهمّ عندهم يقين إنهم هينتصروا بسبب عددهم الكبير ده،\nوبالتالي استهانوا بقوة العدو، وبقوا ماشيين براحتهم في الطريق فاتأخروا وقطعوا المسافة في أربعة ايام وكان المفروض يقطعوها في نص يوم،\nوكانت النتيجة إن مالك بن عوف وصل لوادي حنين قبلهم ونشر قواته في الأماكن المناسبة، واحتل المواقع الاستراتيجية، واستراح جيشه بصورة كافية قبل المعركة، فكل ده كان في صالح المشركين\nولو تفتكروا في غزوة بدر ده بالضبط إللي المسلمين كانوا عملوه، وصلوا قبل جيش قريش واختاروا مكان المعركة وعرفوا ياخدوا المواقع إستراتيجية، وكل ده كان سبب من أسباب النصر،\nلكن هنا لما أعجبتهم الكثرة بدأوا يقللوا من الاهتمام بالتفاصيل، يعني المخابرات الإسلامية لم تتعامل مع الوضع  بدقة كافية، وبالتالي لم تكتشف الكمائن إللي زرعها مالك بن عوف حول وادي حنين، \nعشان كده لما دخلوا وادي حنين حصلت لهم الهزيمة بعد دقائق من بداية المعركة،\nدخلوا قاتلوا جيش المشركين في وادي حنين بقوة وكمان هزموهم في البداية،\nلأ وإيه، ده المشركين من جيش هوازن بدأوا يهربوا وظهرت الغنائم فانطلق المسلمون الطلقاء يجمعوا الغنائم، \nوفجأة بدأت السهام والرماح تنزل على جيش المسلمين زي المطر، وحصل الهروب إللي قلنا عليه، وكل الأحداث حصلت بسرعة في دقائق معدودة \nحصلت الهزيمة العامة في جيش المسلمين وهربوا ولم تنفعهم كثرتهم زي ما ربنا قال:\n\"وَيَوْمَ حُنَيْنٍ إِذْ أَعْجَبَتْكُمْ كَثْرَتُكُمْ فَلَمْ تُغْنِ عَنْكُمْ شَيْئًا وَضَاقَتْ عَلَيْكُمُ الأَرْضُ بِمَا رَحُبَتْ ثُمَّ وَلَّيْتُمْ مُدْبِرِينَ\"\nومتبقاش غير رسول الله ﷺ زي ما قلنا ومعاه بعض أصحابه لم يهربوا.\nطبعا مش عايزة أقولكم بقى عن إحساس مالك بن عوف في اللحظة دي وهو شايف إن خطته نجحت والمسلمين انهزموا وبدأوا يهربوا، وإن رأيه هو إللي كان صح و دُريد بن الصمة طلع مبيفهمش حاجة \nبس مالك بن عوف مش فاهم إن انتصاره المؤقت على المسلمين ده كان بسبب الخلل إللي حصل ودخول العجب في قلوبهم وإن هو مجرد سبب ربنا سخّره عشان يعلمهم درس مهم في التوكل على الله وعدم الأعجاب بالنفس\n◇طيب احنا بقى يا جماعة إزاي نستفيد من موقف انهزام المسلمين في حنين بسبب العجب في حياتنا العملية\nهقولكم مثال وانتم قيسوا عليه، \nفي ناس ساعات بتشتكي مثلا إنها كانت بتحفظ القرآن ومستمرة في الحفظ وقطعت شوط كبير جدا وقربت تختم حفظه، وفجأة توقفت ومهما حاولوا يرجعوا للحفظ مش عارفين، \nمع إنهم مش بيعملوا معاصي مثلا فنقول يمكن بسبب الذنوب ولّا حاجة، لأ، دول ماشيين تمااام في كل حاجة بس فجأة كده مبقوش عارفين يحفظوا، إيه السبب\nغااالبا السبب هنا بيكون إن القلب دخل فيه عُجب من غير ما الواحد يحس،\nفمن رحمة ربنا بقى إنه خلّى الشخص ده يقف عشان يراجع نفسه ويصلّح الخطأ القلبي ده؛ لأن العُجب من مُحبطات الأعمال،\nيعني لو الإنسان استمر في حفظ القرآن وقلبه فيه عجب هييجي يوم القيامة ميلاقيش الأجر إللي كان متوقعه، وبالعكس، ده ممكن يكون من أول الناس إللي هتدخل النار كمان تخيلوا\nويدخل معانا قيام الليل والصدقة والصيام وكل الأعمال الصالحة، فلما الواحد فينا يلاقي نفسه توقف عن عمل صالح كان بيعمله 《بدون أي سبب واضح》 أول حاجة يفكر فيها ويسأل نفسه كده هل دخل في قلبه عُجب من غير ما أحس ولّا لأ\nومع صدق الإنسان ربنا هيخليه يشوف العيب فين بالضبط وهيقدر يعالجه بعون الله\nعرفنا احنا كده السر ورا الهزيمة السريعة لجيش المسلمين في بداية معركة حُنين، نشوف بقى رسول الله ﷺ عمل إيه عشان يقدر يكمل المعركة ويخرج بالمسلمين من الأزمة الكبيرة دي،\nرسول الله ﷺ بيقدم لنا منهج عملي واضح للخروج من الأزمات إللي زي دي، أول حاجة عملها كانت:\n◇ خلّى نفسه قُدوة أمام الجيش فثبت فلم يهرب،\nلأن لو هرب القائد فمفيش أي أمل لثبات الجنود، \nومش بس رسول الله ﷺ ثبت، لأ، ده بدأ يركض بدابته ناحية الكفار وكان العباس عم رسول الله ﷺ ماسك لِجام الدابة عشان خايف على رسول الله ﷺ إنه يُسرع ناحية الأعداء ويجتمع عليه المشركون ويؤذوه،\nولكنه استمر في الدخول في وسط المشركين وهو يقاتل ونزل من على دابته وتقدم وهو ويقول بأعلى صوته:\nأنا النبي لا كَذِب، أنا ابن عبد المطلب ، هَلُمُّوا إليّ أيها الناس! أنا رسول الله! أنا محمد بن عبد الله!\nرسول الله ﷺ كان عارف إن ثبات القائد هيترتب عليه ثبات الجنود، وإذا فكر القائد في النجاة بنفسه فمفيش شك إن الجنود سيُحبطون إحباطاً يمنعهم من أي مقاومة،\nأما إذا ثبت القائد وتقدّم وجاهد وضحى بنفسه فدي أعظم الدروس التربوية لجيشه ولأمته،\nفعلا ملوش مثيل ﷺ\nعارفين، الصحابة بعدين كانوا بيقولوا إنهم لما كان بيشتد عليهم القتال كانوا بيحتموا برسول الله ﷺ من قوته وشجاعته وثباته ﷺ\n◇النقطة التانية إللي عملها رسول الله ﷺ:\nاعتماده على المَوثُوق بهم من الجنود،\nرسول الله ﷺ كقائد أيوة ثبَت لكنه فرد لوحده ميقدرش يعمل حاجة من غير جنود يساعدوه،\nلكن مش أي جنود بقى، احنا عايزين الجنود إللي نقدر نثق بدينهم، ونطمئن لعقيدتهم،\nعشان كده رسول الله ﷺ أمر العباس وكان من الثابتين معاه  إنه ينادي على فئة معينة من المسلمين،\nلم يأمره إنه ينادي على الاثنا عشر ألف، ولا حتى العشر آلاف كلهم، ولكن أمره ينادي على إللي عاهدوه قبل كده على عدم الفرار، \nأيوة همّ هربوا دلوقتي في أول المعركة لكنهم أكيد لو افتكروا بيعتهم هيرجعوا على طول لرسول الله ﷺ،\nوهيرجعوا بسرعة لحالتهم الأولى من البذل والعطاء والجهاد بمجرد التذكير؛ لأن معدنهم شديد النقاء، وربنا نفسه قال إنه رضي عنهم،\nأمره إنه ينادي أصحاب الشجرة...أصحاب بيعة الرضوان إللي شهدوا صلح الحديبية وفتحوا خيبر بعد كده،\nالألف وأربعمائة إللي ربنا قال عنهم:\n\" لَقَدْ رَضِيَ اللَّهُ عَنِ الْمُؤْمِنِينَ إِذْ يُبَايِعُونَكَ تَحْتَ الشَّجَرَةِ فَعَلِمَ مَا فِي قُلُوبِهِمْ فَأَنْزَلَ السَّكِينَةَ عَلَيْهِمْ وَأَثَابَهُمْ فَتْحًا قَرِيبًا\"\nبدأ العباس ينادي بأعلى صوته وكان صوته عالي جدا رضي الله عنه كأنه بيتكلم في ميكروفون\nفنادى وقال:\nيا أصحاب الشجرة! يا أصحاب السَّمُرَة! يا أصحاب الشجرة!\nيا أصحاب السَّمُرَة! وهكذا..\nوالسَّمُرَة معناها الشجرة، وبعدين رسول الله ﷺ قال له ينادي على الأنصار، فنادى العباس:\nيا أنصار الله! يا أنصار رسوله! ثم رسول الله ﷺ خص بالنداء الخزرج، فقال للعباس ينادي على الخزرج، فقال العباس:\nيا بني الخزرج! يا بني الخزرج! ثم رسول الله ﷺ خص بالنداء أكثر وأكثر وأكثر، فأمر العباس إنه ينادى على بني حارثة من الخزرج وهم من خير دُور الأنصار كما قال رسول الله ﷺ،\nدلوقتي طلع نداء لأصحاب الشجرة، وطلع نداء للأنصار من أصحاب الشجرة، ونداء أخص للخزرج من الأنصار، ونداء أخِير أخص لبني حارثة من الخزرج،\nفعملوا إيه بقى إللي سمعوا النداء، العباس بيحكي ويقول :\n\"فَوَاللَّهِ، لَكَأنَّ عَطْفَتَهُمْ حِينَ سَمِعُوا صَوْتي عَطْفَةُ البَقَرِ علَى أَوْلَادِهَ\"\nيعني رجعوا بسرعة جدا زي البقر إللي بترجع تدافع عن أولادها الصغار، وقال الأنصار في لحظة واحدة وبصورة جماعية وبحماس: يا لَبَّيْكَ، يا لَبَّيْكَ\nوجاءوا من كل مكان في أرض الموقعة، حتى إنهم مكنوش شايفين رسول الله ﷺ  من شدة تزاحم الناس، \nوكان الرجل فيهم لما يلاقي صعوبة في العودة؛ لأن الدابة إللي راكب عليها في عكس الاتجاه كان يترك الدابة وينزل ويمشي على قدميه لحد ما يلحق برسول الله ﷺ\nوبدأ يتجمع المسلمون حول رسول الله ﷺ لحد ما وصلوا للمائة وبدأ القتال بين المشركين والمسلمين،\nولما اشتدت المعركة أخذ رسول الله ﷺ حصَياتٍ فرمى بهنَّ وجوهَ الكفَّارِ، يعني أخد تراب من الأرض ورماه في وجوه الكفار وقال: شَاهَت الوجوه، \nفدخل التراب في عيون وأنوف جميع الكفار، وكانت هنا نقطة تحوّل فارقة في موقعة حنين\nوعمل رسول الله ﷺ الخطوة الثالثة والأخيرة في علاج الازمة وهي :\n◇ تذكير الصحابة بأن النصر من عند الله عز وجل:\nفرفع رسول الله ﷺ صوته وهو يقول:\n\"انهزِموا وربِّ الكعبةِ انهزِموا وربِّ الكعبةِ\"\nوبدأ رسول الله ﷺ يدعو في إلحاح:\nاللهم أنزل نصرك، اللهم إني أنشدك ما وعدتني، اللهم لا ينبغي لهم أن يَظهروا علينا، اللهم أنزل نصرك\nفي اللحظات دي اتعالج المرض الخطير إللي أصاب المسلمين يوم حنين، وأدركوا من كل قلبهم إن الناصر الحقيقي هو الله عز وجل، واستوعبوا معنى:\n\"وَمَا النَّصْرُ إِلَّا مِنْ عِنْدِ اللَّهِ إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ\"\nوبدأت فعلا الهزيمة تتحول إلى نصر\nإيه إللي حصل بعد كده؟\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 201, "l": "الجزء 175 | احداث السنه الثامنه من الهجرة | بداية حصار الطائف", "u": "https://www.facebook.com/groups/710210019782034/permalink/836545887148446/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وخمسة_وسبعون\n#أحداث_السنة_الثامنة_من_الهجرة\n#بداية_حصار_الطائف\nاتكلمنا المرة الأخيرة عن سبب هزيمة جيش المسلمين في معركة حُنين وشوفنا إزاي رسول الله ﷺ عالج المشكلة واستطاع إنه يجمّع المسلمين حوله مرة تانية،\nولما الصحابة إللي سمعوا نداء العباس رجعوا يدافعوا عن رسول الله ﷺ ويقاتلوا معاه؛ ربنا أنزل السكينة عليهم، \n\"ثُمَّ أَنزَلَ اللَّهُ سَكِينَتَهُ عَلَى رَسُولِهِ وَعَلَى الْمُؤْمِنِينَ \"\nوبدأ القتال الشديد بين الصحابة إللي اتجمعوا حول رسول الله ﷺ وبين جيش المشركين،\nهنا بقى لما تغير واقع المسلمين وثبتوا؛ ربنا أَذِن بنزول النصر \nوكالعادة يأتي النصر بصورة لا يتوقعها المسلمون عشان الكل يعرف إن النصر فعلا من عند الله \n◇أول عامل من عوامل النصر:\n إن ربنا أنزل السَّكِينة على رسول الله ﷺ وعلى المؤمنين الثابتين زي ما قلنا من شوية، والسَّكِينة معناها الطمأنينة والهدوء والاستقرار، وراحة البال والثبات،\nفالمسلمين كان بالهم رايق ومطمنين وثابتين مع إنهم مجموعة صغيرة بيواجهوا خمسة وعشرين ألف \n◇ثاني عامل من عوامل النصر:\nإن ربنا ألقى الله الرعب في قلوب الكافرين فبدأوا يهربوا، متنازلين بسهولة شديدة عن النصر إللي كانوا حققوه\n◇ثالثا:\nأنزل الله عز وجل الملائكة تقاتل مع المسلمين،\n\" وَأَنزَلَ جُنُودًا لَمْ تَرَوْهَا\"\nوسبحان الله في دقائق معدودة الهزيمة تتحول لنصر، ويهرب الجيش إللي عدده خمسة وعشرين ألف وإللي كان متجهز بالدروع والسلاح وكان مستحوذ على الأماكن الاستراتيجية في أرض المعركة\nلما ربنا بيأذن بالنصر احنا ساعتها منسألش عن الأسباب المادية، لكن نفهم معنى:\n\"وَمَا النَّصْرُ إِلا مِنْ عِنْدِ اللَّهِ\"\nكل واحد من الصحابة إللي حضر القتال ده بقى بعدين بيحكي إللي شافه في أرض المعركة،\nيعني واحد من الصحابة قال إن رسول الله ﷺ لما أخد تراب من الأرض ورماه في وجوه الكفار ودخل التراب في عيون وأنوف جميع الكفار المشركين بقوا يقاتلوا قتال ضعيف وبدأوا يهربوا وهم أَذِلة،\nوواحد تاني من الصحابة قال: لم يثبتوا لنا حَلْب شاة \nيعني المشركين انهزموا في وقت قصير جدا، مكملوش الزمن إللي الواحد بياخده في حَلْب الشاة،\nزي ماحنا بنقول كده : ده مخدش في إيدي غَلْوَة\nوكان من المواقف إللي حصلت في أرض المعركة إن أم سُلَيم صاحبة أغلى مهر في الإسلام إللي اتكلمنا عنها في الجزء الخامس والستين؛ اتخذت خنجر وخلته معاها، ومكنش من عادة النساء القتال، \nهمّ كانوا بيخرجوا مع الجيش لتطبيب الجرحى مثلا أو يكونوا مع أزواجهم، لكن مكنوش بيقاتلوا إلا لو اضطروا لكده،\nيعني أم سليم لما أخذت الخنجر وخلته معاها وزوجها أبو طلحة شافها قال لرسول الله ﷺ:\nيا رسول الله هذه أم سليم، معها خنجر!\nفسألها رسول الله ﷺ:\nما هذا الخنجر ؟!\nيعني انتِ واخدة الخنجر ده ليه، فقالت له:\nاتّخذْتُه، إن دَنَا مني أحد من المشركين بقَرْتُ بهِ بطنَه\nيعني بتقوله أنا أخدت الخنجر وخليته معايا عشان لو واحد من المشركين قرب مني أشق بطنه،\nودي شجاعة ظاهرة من أم سليم رضي الله عنها، مش أي حد يثبت في أرض، يعني ممكن أشجع الرجال يهرب في مرحلة من المراحل، فما بالكم بامرأة طبيعتها الضعف أصلا\nفلما سمعها رسول الله ﷺ قعد يضحك\nفقالت له:\nيا رسول الله، اقْتُلْ مَن بَعْدَنَا مِنَ الطُّلَقَاءِ انْهَزَمُوا بكَ\nيعني هي عايزة رسول الله ﷺ يقتل الطُّلقاء إللي أظهروا الضعف وهربوا من أول المعركة،\nفقال لها رسول الله ﷺ: يا أم سليم! إن الله قد كَفَى وأحسن.\nيعني خلاص ربنا كفانا أمرهم وأبعدهم عنا، فمش هنُسِيء احنا لهم، وده من حسن خُلُقه ﷺ\nومن المواقف إللي حصلت كمان في أرض المعركة قَتْل حامل راية المشركين، \nوكان الرجل حامل راية المشركين ده راكب على جمل لونه أحمر وماسك في إيده رمح طويل متعلق عليه راية سوداء والمسلمين من أمامه وهوازن خلفه،\nفكان لما يعرف يوصل لحد من المسلمين برمحه الطويل ده يقوم طاعنه،\nولما يكون بعيد عنهم يقوم رافع الراية ويتحرك والمشركين يتحركوا وراه،\nوفضل يعمل كده طول المعركة،\nوهو بقى على الحال ده انقض عليه علي بن أبي طالب ومعاه رجل من الأنصار عشان عايزين يقتلوه،\nفجاءه علي من خلفه وضرب الجمل على عُرْقُوبِه يعني على رجل الجمل من الخلف فسقط الجمل، والأنصاري وثب على الرجل فضربه ضربة أَطَنّ قدمَه بنصف ساقه،\nيعني الأنصاري نط على الرجل المشرك وضربه على رجله بالسيف قطعهاله مع نصف ساقه وسقطت الراية،\nواشتد القتال وانهزم المشركون وبدأوا في الهروب في كل اتجاه والرعب يملأ قلوبهم، \nوتركوا وراءهم أموالهم وأنعامهم وأكثر نسائهم وأولادهم، وزي ما قال دريد بن الصمة :\n\"وهل يَرد المنهزم شيء؟\"\nربنا بقى وصف موقف المشركين بعد عودة المسلمين إلى ربهم سبحانه وتعالى بكلام بليغ مختصر مُعجِز، قال عز وجل:\n\"وَعَذَّبَ الَّذِينَ كَفَرُوا وَذَلِكَ جَزَاءُ الْكَافِرِينَ\"\n◇من العذاب أن تأخذ قرار الفرار.\n◇ من العذاب أن تهرب وأنت الأكثر عَدداً وعُدة.\n◇من العذاب أن تتنازل عن حصاد السنين من المال والأنعام في لحظة واحدة هكذا..\n◇من العذاب أن تتخلى عن زوجتك وأولادك؛ لأن الرعب يملأ قلبك.\n◇من العذاب أن تشعر أن كل شيء يُطاردك حتى الجماد،\nوده فعلا حصل حقيقي، \nوإللي بيحكي ده واحد اسمه عمرو بن سفيان الثقفي، كان من المشركين إللي هربوا في حنين وأسلم بعدين وحَسُن إسلامه، بيقول:\nفانهزمنا، فخُيّل إلينا أن كل حجر وشجر فارسٌ يطلبُنا\nيعني بيقول إنهم لما انهزموا وبدأوا يهربوا بقوا حاسين إن كل الحجر والشجر اتحولوا لفرسان بيجروا وراهم\nفأسرع في الهرب لحد ما عرف يدخل الطائف،وده كان من نصر الله للمسلمين\nجيش المشركين هرب في ثلاثة اتجاهات:\n◇جزء هرب إلى أَوْطاس وهو جانب من وادي حنين.\n◇والجزء الثاني هرب إلى منطقة نخلة إللي الجن جاءوا واستمعوا لرسول الله ﷺ فيها وهو راجع من الطائف قبل الهجرة لو تفتكروا.\n◇والجزء الثالث والأساسي هرب إلى مدينة الطائف،\nهرب جميع جيش المشركين بالصورة المخزية دي وهرب معهم قائدهم مالك بن عوف إللي دفعهم للمهزلة العسكرية دي من البداية\nهربوا وتركوا الغنائم وأخذها المسلمون، وتحقق قول رسول الله ﷺ:\n\" تلك غنيمة المسلمين غداً إن شاء الله\"\nوكانت الغنائم دي أكبر وأعظم غنائم تحصل في معركة واحدة في تاريخ العرب كلها؛ لأن مالك بن عوف جاء بكل صغيرة وكبيرة في قومه، عشان تبقى من نصيب المسلمين\nعارفين الغنائم كانت أد إيه\n◇ عدد السّبْي ستة آلاف امرأة ده غير الأطفال\nمتخيلين نساء كانوا حرائر معززين مكرمين في أهلهم فجأة يتحولوا لإماء مسلوبة منهم حريتهم، وكل ده بسبب مالك بن عوف\n◇عدد الإبل في الغنائم أزيد من الأربعة وعشرين ألف.\n◇عدد الأغنام أكتر من أربعين ألف.\n◇والفضة أكتر من أربعة آلاف أوقية، يعني ما يساوي مائة وخمسون كيلو جرام فضة، ده غير الذهب\nالغنائم دي تساوي الملايين في عصرنا دلوقتي يا جماعة\nيعني الجمل الواحد مثلا ثمنه من 48 ألف جنيه ل56 ألف جنيه، \nفتخيلوا أكثر من 24 ألف جمل،\nوغير الأبقار والأغنام، ثروة فعلا، وكلها دلوقتي في إيد المسلمين، سبحان الله نصر كبير جدا للمسلمين محدش كان يتوقعه ولا يحلم بيه\nوالمفاجأة الأكبر إن عدد المسلمين إللي قُتلوا في معركة حنين هم خمسة فقط، أما عدد قتلى المشركين فكانوا سبعين رجل،\nمع إن إللي يشوف أعداد الفريقين يظن إن هيبقى في قتلى بالمئات، ويمكن بالآلاف \nلكن ده محصلش؛ لأن في بداية المعركة المسلمين هربوا من غير ما يكون في قتال يُذكر،\nوفي آخر المعركة المشركين همّ إللي هربوا من غير ما يكون في قتال تقريبا بعد ما تحولت الهزيمة لنصر بسبب التغير القلبي إللي حصل وإللي محدش مطلع عليه غير ربنا\nحصل انحراف وتغير في القلب في بداية المعركة وأُعجب المسلمون بنفسهم؛ فكانت النتيجة هي الفرار،\nوأول ما تغير قلبهم ورجعوا للمفهوم الصحيح وهو إن النصر من عند الله؛ ربنا أنزل عليهم النصر\n☆لو جينا احنا بقى نشوف الواقع بتاعنا هنلاقي إن حنين بتتكرر في حياتنا من غير ما ناخد بالنا،\nيعني المسلمين كانوا معجبين بعددهم الكتير وبالتالي كانوا 《معتمدين》 على أعدادهم 《وواثقين》 فيها ونسيوا إن النصر من عند الله،\nكذلك في ناس تلاقيها بتتوكل وتعتمد على الطبيب الماهر المشهور اعتماد كلي لدرجة إنهم ميفكروش يدعوا ربنا بإن يشفي مريضهم،\nوفي ناس ممكن تعتمد وتوقن وتتوكل على شخص عنده سُلْطة ونفذوذ عشان يعملهم مصلحة وناسيين اللجوء لربنا وإنه أعلى من أي سُلْطة وإن كل شيء بيده\nوغيرها وغيرها من الأمثلة، \nفطول ما الإنسان بيتعلق قلبه بالأسباب وينسى مُسبب الأسباب هيحصل الفشل والخوف والفزع والهروب، ومش هيثبت ولا ينجح ولا ينتصر ولا يَأمن إلا إللي يعمل زي الصحابة؛ \nأخذوا بالأسباب لكن الاعتماد الكااامل كان على رب الأسباب سبحانه وتعالى\nبالنسبة بقى لتوزيع الغنائم فرسول الله ﷺ أجّل التوزيع ده لحد ما يتصرف مع جيش هوازن إللي هرب وتحصّن في حصون الطائف المنيعة،\nفخلّى رسول الله ﷺ كل الغنائم في وادي اسمه وادي الجُعْرَانة جنب وادي حُنين، \nوخلّى واحد من الصحابة وهو بُدَيْل بن وَرْقاء المسؤول عن الغنائم والسّبي لحد ما رسول الله ﷺ يرجع، وكان بُديل أسلم بعد فتح مكة،\nقبل ما رسول الله ﷺ ينطلق إلى حصون الطائف بدأ يتفقد الجرحى ويدفن من قُتل من المسلمين،\nوكان رسول الله ﷺ بيسأل عن خالد بن الوليد رضي الله عنه ويقول:\n\"مَن يَدُل على رَحل خالد بن الوليد\"\nيعني مين يعرف مكان خالد بن الوليد، وكان رضي الله عنه من القادة إللي اتصابوا في المعركة،\nفلما دلّوا رسول الله ﷺ على مكان خالد توجه إليه رسول الله ﷺ فجاءه وكان مُستند إلى مؤخرة رحله، \nفشاف جرحه ونفث فيه رسول الله ﷺ، يعني نفخ في جرحه فشُفِيَ جرحه بإذن الله، وكان ده من معجزاته ﷺ\nبعد كده انطلق رسول الله ﷺ مع معظم جيش المسلمين إلى الطائف لحصار هوازن وثقيف داخل حصن الطائف؛ لأن جزء كبير جدا من جيش المشركين كانوا هربوا للطائف،\nوفي نفس الوقت أرسل رسول الله ﷺ سرية لوادي أَوْطاس إللي هرب إليه مجموعة من المقاتلين المشركين زي ما قلنا من شوية، وكان معهم دُريد بن الصمّة، وكانت السرية بقيادة أبي عامر الأشعري، \nوانتصرت السرية دي على المقاتلين المشركين وقُتل دُريد بن الصمة، ورُمِيَ أبا عامر الأشعري بسهم، ومات شهيدا بعدها بوقت قصير رضي الله عنه.\nنرجع بقى لرسول الله ﷺ إللي كان مُتجه للطائف، \nوأنا عايزاكم تتخيلوا وتعملوا مقارنة كده بين موقف رسول الله ﷺ في اللحظة دي وهو متجه للطائف في جيش مهيب قوي،\nوبين موقفه لما كان متجه برده للطائف من إحدى عشرة سنة\nخليني أفكركم كده سريعا ببعض الأحداث\nرسول الله ﷺ كان متجه للطائف وهو في أشد حالات الحزن والضيق، \nوكان ماشي على قدمه ومكنش معاه غير  زيد بن حارثة رضي الله عنه،\nوكان الكلام ده بعد موت عمه أبي طالب، وكمان بعد موت السيدة خديجة، \nومكنش معاه في مكة إلا قليل من المؤمنين كان عددهم ميعديش مائة واحد من الصحابة، \nوكانوا مُشردين في الحبشة، وكان الوضع في غاية المأساة،\nوطبعا انتم مش ناسيين الطائف عملوا معاه إيه وزوّدوا آلامه إزاي بتصرفاتهم\nودلوقتي رسول الله ﷺ جاي في موقف محدش كان يتصوره ولا يتخيله أبدا لا من أهل مكة ولا من أهل الطائف ولا أي حد من أهل الجزيرة بكاملها، \nرسول الله ﷺ جاء لهم عزيزاً منتصراً مُمَكّناً رافعاً رأسه، مُحاط بجيش مؤمن جرّار يُزلزل الأرض من حوله، يرفع راية لا إله إلا الله، محمد رسول الله،\nلعلّ رسول الله ﷺ في اللحظات دي كان بيتذكر الأحداث إللي حصلت معاه،\nلعله تذكر زيد بن حارثة إللي كان معاه في الرحلة، لكنه مش موجود في الرحلة التانية دي عشان يشوف النصر إللي رسول الله ﷺ فيه،\nولعل رسول الله ﷺ تذكر عبد ياليل بن عمير الثقفي إللي كان سخر منه وقاله :\nده أنا أقطع أستار الكعبة لو ربنا أرسلك، وعبد ياليل ده بالمناسبة هرب مع إللي هربوا من أرض حنين وراح استخبى في الطائف\nولعل رسول الله ﷺ تذكر عدّاس الفتى النصراني إللي أسلم على يده ﷺ،\nولعله تذكر جبريل لما جاءه بملك الجبال عشان يهلك المشركين، ولعل...ولعل....\nكلها ذكريات وأيام عدت لكن إللي اتبقى هو العمل واجتهاد رسول الله ﷺ في الدعوة،\nودلوقتي رسول الله ﷺ بيحصد ثمار عمله إللي قدمه خلال السنين إللي فاتت\nوصل جيش المسلمين إلى الطائف، والكل توقع معركة كبيرة هتحصل بين تجمع هوازن وثقيف في حصون الطائف وبين جيش المسلمين، وخصوصا إن نساءهم وأموالهم في إيد المسلمين دلوقتي فعلى الأقل هيقاتلوا باستماتة عشان يسترجعوا نساءهم وأولادهم،\nلكن إللي حصل كان غير المتوقع\nدخلوا الحصون بتاعتهم ورفضوا إنهم يخرجوا منها لقتال المسلمين،\nمع إن عددهم وعُدتهم أضعاف المسلمين، وكمان بيقاتلوا في أرضهم إللي حافظينها، لكن الخوف إللي في قلوبهم من المسلمين خلاهم يرفضوا يقاتلوا المسلمين مرة تانية واكتفوا بفضيحة حنين\nلما رسول الله ﷺ شاف إن أهل الطائف من هوازن وثقيف رافضين الخروج لقتال المسلمين، لم يتنازل رسول الله ﷺ   بسهولة وأصابه اليأس وقرر الرجوع مثلا،\nلأ، ده قرر فرض الحصار على حصون الطائف المنيعة، يمكن يفقدوا الأمل ويخرجوا\nلكن أهل الطائف مقعدوش ساكتين برده، بقوا يرموا السهام والرّمَاح على جيش المسلمين،\nوكان المسلمون همّ كمان بيرموا عليهم سهام، لكن سهام المسلمين مكنتش بتوصل لداخل الحصن؛ لأن الحصن عالي وهم واقفين على الأرض،\nفكان الموضوع صعب عليهم جدا، وأُصيب المسلمون بجراح،\nواستخدم رسول الله ﷺ الوسائل المُتاحة عشان يحاول يفتح حصن الطائف أو يخلّي المشركين يخرجوا من الحصن ويبقى في قتال بينهم، لكن مفيش فايدة، واستمر الحصار\nوكان من الوسائل البارعة إللي استعملها رسول الله ﷺ للضغط على المشركين هي محاولة تَفْكِيك الصف داخل الحصون،\nبمعنى، إن رسول الله ﷺ نادى على العبيد في داخل الحصون وقال:\n\"أَيُّما عبدٌ نزل من الحصن وخرج إلينا فهو حُر\"\nيعني أي عبد من العبيد إللي داخل الحصن خرج من الحصن وجالنا؛ هيكون حر،\nوكان العبيد في المجتمع العربي القديم كتير جدا، وكان من  سياسة الإسلام تحرير العبيد في كل مناسبة ممكنة،\nفكانت دي فرصة كويسة لتحرير بعض العبيد من صفوف المشركين،\nفهؤلاء العبيد في الغالب هيدخلوا في الإسلام، وبكده هيتم إنقاذهم من ظلمات الكفر، \nوأهل ثقيف هيفقدوا طاقة هؤلاء العبيد، ده غير إنهم هينقلوا للمسلمين الأخبار من داخل الطائف\nففي هنا أكتر من فائدة في القرار ده؛ وده كان من حكمته وبراعته العسكرية ﷺ\nوفعلا بعض العبيد بدأوا يخرجوا من الحصون عن طريق النزول من على الأسوار، لحد ما وصل عددهم إلى ثلاثة وعشرين من العبيد، \nواكتشفت ثقيف الموضوع وشددت الحصار على الأسوار، ومنعت خروج بقية العبيد،\nواستفاد المسلمون من خروج الثلاثة والعشرين عبد دول، وأهم استفادة كانت أمرين:\n◇أعظم الأمرين:\nهو إضافة ثلاثة وعشرين رجلاً إلى أمة الإسلام\n \nلأن زي ما رسول الله ﷺ قال:\n\" لأنْ يهْدِيَ اللَّه بِكَ رجُلًا واحِدًا خَيْرٌ لكَ من حُمْرِ النَّعم\"\n◇الأمر الثاني:\n معرفة بعض المعلومات العسكرية الخطيرة\nلأن العبيد دول أخبروا رسول الله ﷺ إن الطعام والشراب إللي في داخل الطائف  يكفي للمطاولة والصبر على الحصار سنة على الأقل أو عدة سنوات،\nوالمعلومة دي مهمة جدا؛ لأن بالوضع ده الحصار مش هيبقى يوم أو يومين ولا شهر ولا شهرين، \nده عندهم طعام يكفي لسنة أو أكثر، \nيعني بالعربي كده أهل الطائف مش خسرانين حاجة من الحصار ده\nلكن المسلمين بقى مش هيقدروا يستنوا في المكان ده كتير؛\nلأن القوات الإسلامية مش مجرد فرقة إسلامية من الجيش الإسلامي،\nولا مجرد جيش لدولة، ده القوات الإسلامية دي هي المجتمع المسلم كله\nورسول الله ﷺ لم يترك في المدينة إللي هي عاصمة الدولة الإسلامية إلا القليل من الرجال لحراسة النساء والأطفال والديار، \nوكمان في كثير من القبائل إللي دخلها الإسلام حديثاً، والقبائل دي محتاجة متابعة مستمرة خوفاً من انقلابها إلى الكفر والهجوم على المدينة،\nوفي لسه كثير من القبائل لم تسلم في الجزيرة العربية، فممكن يهجموا على المدينة برده،\nومننساش اليهود في خيبر إللي على مسافة قريبة من المدينة، وهم على عهد مع رسول الله ﷺ وممكن يخالفوا العهد وينقضوه كعادتهم،\nوكمان أهل مكة إللي لسه كانوا على الجاهلية من فترة قريبة جدا، \nده غير الغنائم الضخمة المتروكة في وادي الجعرانة\nيعني في أمور ضخمة جدا وكتيرة ميقدرش رسول الله ﷺ  إنه يسيبها ويقعد هنا في حصار الطائف إلى أجل غير مسمى\nفيا ترى بقى رسول الله ﷺ هيعمل إيه\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 202, "l": "الجزء 176 | احداث السنه الثامنه من الهجرة | فك الحصار عن الطائف والرجوع  الي الجعرانه", "u": "https://www.facebook.com/groups/710210019782034/permalink/836546197148415/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وستة_وسبعون\n#أحداث_السنة_الثامنة_من_الهجرة\n#فك_الحصار_عن_الطائف_والرجوع_إلى_الجُعرانة\nاتكلمنا المرة إللي فاتت عن فرض رسول الله ﷺ الحصار على الطائف، وشوفنا بعض محاولاته لفتح الحصن لكن الحصن كان منيع وأهل الطائف عندهم أكلهم وشربهم إالي يكفيهم سنة وأكثر،\nورسول الله ﷺ مش هينفع يفضل في الحصار ده إلى أجل غير مسمى للأسباب إللي قلناها المرة إللي فاتت، \nوفترة الحصار طالت جدا يعني رسول الله ﷺ قعد أربعين ليلة محاصر لحصن الطائف من غير أي فايدة\nفاستشار رسول الله ﷺ واحد من أصحابه من أصحاب الخبرة العسكرية والرأي السديد،\nلما تعرفوا اسم الصحابي إللي رسول الله ﷺ استشاره ده هتستغربوا جدا\nالصحابي ده اسمه : 《نوفل بن معاوية الدَّيْلِي》\nنسيتوه صح\nخلوني أفكركم بيه كده\nنوفل بن معاوية ده هو زعيم بني بكر، القبيلة إللي دخلت مع  قريش في صلح الحديبية، \nوهو إللي قاد قومه لقتل خزاعة، وإللي كان سبب في نقض صلح الحديبية، وإللي دخل الحرم المكي واستمر في عملية قتل رجال خزاعة،\nوإللي رد بالرد الكفري على قومه لما قالوا له: يانوفل إلهك إلهك، فقال لهم: يا بني بكر! لا إله لكم اليوم،\nوإللي كان سبب في خروج رسول الله ﷺ إلى فتح مكة المكرمة وبعدين حنين، وبعدين الطائف،\nسبحان مقلب المقلوب والله، \nمن شهرين ثلاثة بس نوفل بن معاوية الديلي عمل الجرائم دي كلها وبعدها أسلم وحَسُن إسلامه وانضم إلى الجيش المسلم وبقى مستشار أمين من المستشارين العسكريين لرسول الله ﷺ\nواحنا وإن كنا نعجب من تحوّله من الكفر إلى الإيمان، ومن الغدر إلى الأمانة، ومن حِلفه لقريش إلى دخوله في الإسلام،\nفالعَجَب كل العجب في موقف رسول الله ﷺ معاه،\nرسول الله ﷺ معملش زي إللي القادة بيعملوه مع قادة الجيش المعادي بالقتل والإبادة والسجن والتعذيب، زي بنشوف في كل مكان،\nلكنه وظّف طاقته في خدمة الإسلام، وده كان من عادته في كل حياته ﷺ،\nولو تفتكروا في سرية ذات السلاسل لما جعل عمرو بن العاص قائد السرية دي بعد ما أسلم بوقت بسيط،\nفرسول الله ﷺ بلغ قمة الحكمة في التعامل مع الناس، وقمة الحكمة في إِنزال الناس منازلهم، وقمة الحكمة في احترام أرائهم واستغلال قدراتهم،\nوهو يعلم ﷺ إن القوّاد إذا هُمّشوا وأُهملوا مش بس هتضيع قواتهم، لأ، ده ممكن يكونوا وبال على الأمة\nفلما استشار رسول الله ﷺ نوفل بن معاوية الديلي يعملوا إيه في الحصار إللي طال ده، قال له معاوية:\n\"هم ثعلبٌ في جُحر، إن أقمتَ عليه أخذْتَه، وإن تركته لم يَضُرك\"\nيعني هو بيشبه أهل ثقيف بالثعالب، وده حقيقي ومشتهر عنهم وسط العرب، حتى إن عيينة بن حصن قال عنهم:\n\"إنهم قوم مناكير\" يعني قوم أصحاب دهاء وفطنة،\nومعاوية بن نوفل بيؤكد إنهم ملهمش مهرب من الحصون دي لما قال:《إن أقمتَ عليه أخذته》\nلكنه في نفس الوقت بيشير لأمر مهم جدا لما قال:\n《وإن تركته لم يضرك》\nالكلمة دي معناها إن شوكة ثقيف وهوازن خلاص اتكسرت ومعنوياتهم هبطت للحضيض، ومش هتقوم لهم قائمة بعد إللي حصلهم في حنين، فهزيمتهم في حنين انتشرت وسط العرب،\nفهو بيقول لرسول الله ﷺ إنه لو صبر على الحصار هيوصل لمراده وغايته من فتح الحصن، لكن تضييع الوقت في حصارهم هيكون ضار بالجيش الإسلامي أكثر من ضرره بثقيف\nفهنا قرر رسول الله ﷺ فك الحصار عن الطائف والانسحاب والرجوع لوادي الجعرانة إللي فيه الغنائم بعد ما شاف إن فعلا مفيش فايدة الحصار،\nفأرسل رسول الله ﷺ إلى عمر بن الخطاب إنه ينادي في الناس ويقول: \"إنا قافلون غداً إن شاء الله\"\nيعني احنا خلاص هننسحب وهنرجع بكرة لوادي الجعرانة،\nلكن بعض الصحابة من المتحمسين اتضايقوا من قرار العودة وترك الطائف من غير ما يفتحوها، فقالوا:\nنذهب ولا نفتح حصون الطائف؟!\nيعني إزاي نمشي من غير نفتح حصون الطائف، فلما رسول الله ﷺ شاف كثرتهم ورغبتهم، احترم رأيهم وكان عايزهم يتعلموا الدرس بصورة عملية، فقال لهم:\nاغدوا على القتال\nيعني ما دام انتم عايزين تقاتلوا خلاص روحوا قاتلوا، فسمح لهم بالقتال في اليوم الثاني، \nوخرج المسلمون للقتال، وفي اليوم ده بالذات أُصيب المسلمون بإصابات شديدة\nومع ذلك رسول الله ﷺ مقعدش يلوم عليهم ويقول لهم مثلا مش قلت لكم، ما كنتم تسمعوا الكلام من الأول بدل الإصابات إللي أصابتكم دي،\nلأ، قال لهم بس:\n《إنا قافلون غداً إن شاء الله》\nوالمرة دي محدش اعترض وقبلوا أمر رسول الله ﷺ واقتنعوا إن مفيش فايدة من القتال، وبدأوا في جمع حاجاتهم والاستعداد للرحيل بسرعة،\nفلما رسول الله ﷺ شاف سرعتهم في جمع رحالهم قعد يضحك ﷺ\nخلاص اتعلموا الدرس وعرفوا إن رأي رسول الله ﷺ هو الأصلح والأصوب\n☆قرار الانسحاب إللي أخذه رسول الله ﷺ ده بيعلمنا درس مهم جدا وهو《الواقعية في الحياة》،\nيعني يا جماعة مش عيب إننا نفشل في أمر من الأمور،\nومش لازم كل معاركنا وكل مشاريعنا تبقى ناجحة،\nلكن المهم إننا منغرقش في العمل من غير ما ندرك إن الهدف بتاعنا غير قابل للتحقيق، لكن برده مش معنى الكلام إننا نيأس بسرعة ونستسلم\nيعني شوفوا رسول الله ﷺ قعد أربعين ليلة في الحصار واستخدم كل الوسائل المتاحة ويقدر يعملها وبذل ما في وسعه، \nومع ذلك مكنش في نتيجة والهدف متحققش، رسول الله ﷺ معاندش بقى وصمم على إكمال الحصار بغض النظر عن الضرر إللي هيحصل للجيش وللدولة الإسلامية بسبب الحصار،\nفالمسألة مش مسألة عِند على أد ما هي مسألة تحقيق الأصلح، \nفمادام الأصلح هو التنازل عن الهدف إللي كان بيسعى لتحقيقه فعادي جدا يتنازل عنه عشان المصلحة الأكبر تتم، فرسول الله ﷺ تقبل في واقعية إنه ينسحب\nوفي فرق كبير جداً بين المُثابرة على أداء عمل يعني المداومة عليه وبين تضييع الوقت،\nفالمثابرة على أداء عمل أمر مطلوب، لكن لازم يكون في مؤشرات للنجاح،\nلازم يكون في مقاييس تشير إلى إن العمل ده يمكن تحقيقه، ولازم الخسائر تكون أقل من الفوائد، عشان كده لازم يكون في متابعة وملاحظة وتقييم المستمر\nأما تضييع الوقت فهو الاستمرار في عمل يستحيل تحقيقه بالإمكانيات المتاحة، أو يتسبب في خسائر أكبر من الفوائد\nهقول لكم مثال للتوضيح من حياتنا العملية وانتم قيسوا عليه،\nواحد مثلا حب يفتح مطعم لبيع كوسة بالباشميل فقط، والقصة دي حقيقية فعلا\nالمهم فتح المطعم وعمل له إعلانات وصرف عليه جامد، ومع ذلك عمّال بيخسر،\nبعض الناس نصحوه وقالوا له إن مش كل الناس بتحب الكوسة بالباشاميل فقال لهم أنا بحبها، \nفهو مش فاهم إنه لازم يبيع إللي الناس بتحبه مش إللي هو بيحبه، وفضل مصمم برده على بيع الكوسة بالباشاميل،\nفهو هنا بيضيع وقته وجهده وفلوسه في حاجة يستحيل تتحقق وملهاش فايدة،\nوالصح إنه كان ينسحب من المشروع الفاشل ده مادام بيتسبب له في خسائر كبيرة\nفرسول الله ﷺ لما شاف إن مفيش فايدة انسحب وتراجع عن تحقيق الهدف ده،\nولأن بعض الصحابة مكنوش مستوعبين الواقعية إللي هو كان  شايفها ﷺ، فخلّاهم يخوضوا التجربة بنفسهم عشان يفهموا بالطريقة العملية وجهة نظر رسول الله ﷺ،\nوموقف رسول الله ﷺ مع الصحابة ده بيعلمنا نقطة مهمة جدا في تربية الأطفال\nساعات عيالنا بيبقوا مصممين على حاجة أو رأي هو غلط واحنا عارفين إنه غلط وبننصحهم وهمّ مش بيستجيبوا،\nفاحنا هنا ممكن نعمل زي رسول الله ﷺ ونخليهم يجربوا بنفسهم عشان يشوفوا نتيجة رأيهم الخطأ وساعتها هيقتنعوا ويعملوا الصح بعدين،\nبعكس مثلا لو صممنا إنهم يعملوا إللي احنا شايفينه صح بالجبر، \nهيفضلوا طول عمرهم مفكرين إنهم صح وإن الأب أو الأم همّ إللي غلط ومتسلطين وهيحصل التمرد من الأبناء في أقرب فرصة، وهينفذوا آراءهم بعدين وهيبقى في أمور أشد وأخطر بكتير من آراءهم البسيطة وهمّ صغيرين\nطبعا يا جماعة الكلام إللي قلته ده\n ميكونش في حاجة فيها حرام ولا حاجة فيها خطر عليهم\nيعني متجيش بنتي مصممة إنها متلبسش الحجاب الشرعي أو عايزة تتفرج على أفلام أو تسمع أغاني وأنا أخليها تجرب عشان تشوف إن إللي بتعمله ده غلط،\nلأ، ده أنا يجب عليّ منعها بكل الطرق لأنها مسؤولة مني وهتحاسب عنها يوم القيامة،\nلكن أنا بتكلم في الأمور العادية، يعني حد من عيالنا عايز يذاكر بطريقة معينة واحنا عارفين إن الطريقة دي غلط وهتضيع له وقته، وبنفهمه كده وهو مش مقتنع وعايز يذاكر بطريقته،\nفبنخليه يذاكر بطريقته ونديله مُهلة معينة ونشوف نتيجة المذاكرة بتاعته إيه، فلما هو يجرب ويلاقي إن طريقته كانت غلط، خلاص مش هيبقى في مشاكل بعدين،\nلكن لو غصبناه ومخليناهوش يجرب، كل مرة هييجي يذاكر هيبقى مقتنع إن طريقة أمه أو أبوه غلط وإن طريقته إللي مجرباهش هي إللي صح\nفلو كان رسول الله ﷺ غصب الصحابة إنهم يرجعوا من غير ما يديهم فرصة القتال كانوا هيفضلوا يقولوا لو كنت سيبتنا يا رسول الله نقاتل كان زماننا فتحنا الحصن،\nلكن من حكمته ﷺ إنه خلاهم يجربوا بنفسهم عشان يقفل الموضوع ده خالص وميكنش له أي أثار سلبية في المستقبل\nأما بقى ليه ربنا لم يُقَدر فتح الطائف، فهو له حكمة سبحانه،\nمن الحكمة دي أمرين:\n◇الأول:\nلو الطائف فُتحت في ظل الظروف الصعبة دي والقتال الشرس والمطاردة لهوازن وثقيف، والقتال في داخل الحصون،\nكان هيُقتل منهم عدد كبير جدا،\nوكان الإسلام هيفقد قوتهم جميعاً؛ لأن هوازن وثقيف أسلموا بعد كده، فلو قُتلوا كنا هنفقد قوتهم وكانت هتبقى عاقبتهم النار،\nوتخيلوا إن الطائف إللي تأخر إسلامهم دول هيكونوا من المدن إللي هتثبت على الإسلام بعد وفاة رسول الله ﷺ ومش هترتد زي باقي العرب\n◇الأمر الثاني:\nإن الانسحاب دون إتمام المهمة فتح لنا باباً أن نفعل المثل إن تعرضنا لنفس الموقف،\nيعني لو المسلمين اتعرضوا لنفس الموقف وحاصروا مدينة ومقدروش يفتحوها فهم يقدروا يعملوا زي رسول الله ﷺ وينسحبوا، وفعلا الموقف ده اتكرر في التاريخ،\nكان المسلمون يحاصروا حصون الأعداء وكان بعض الحصون بتكون صعبة وميقدروش يفتحوها فكانوا بينسحبوا،\nلكن بقى لو كان رسول الله ﷺ أصر على عدم الانسحاب لحد ما يفتح الحصن، كان هيبقى إحراج كبير جداً للأمة الإسلامية؛ لأنه هيبقى لزام علينا إننا نفعل مثله ﷺ؛ لأنه القدوة ويجب اتباعه، \nفلما انسحب رسول الله ﷺ بعد المشاورة فهو كده ترك الأمر لقادة المسلمين ولرأي الشورى،\nيعني لو المسلمين شافوا إن الحصار في وراه فايدة يبقى يصبروا لحد ما يفتحوا الحصن، زي ما حصل في فتح خيبر\nولو شافوا إن الموضوع مستحيل أو خسائره كبيرة يبقى ينسحبوا زي ما حصل في الطائف، وفي الحالتين هم بيتبعوا وبيقتدوا برسول الله ﷺ\nاتجهز الجيش للرحيل وهمّ ماشيين حصل موقف في منتهى الرقة من رسول الله ﷺ،\nبعض الصحابة كانوا لسه متضايقين إنهم مفتحوش حصن الطائف بعد كل ده، فقالوا لرسول الله ﷺ:\nيا رسول الله، ادعُ على ثقيف!\nفقال رسول الله ﷺ :\nاللهم اهدِ ثقيفاً وائْتِ بهم\nرسالة رسول الله ﷺ إنه يوصل بدعوته للناس مش إنه يقتلهم، \nهدفه إنقاذ الناس من النار مش إنه ينتقم منهم،\nمع ذكريات الطائف في المرة الأولى، وواقع الطائف في المرة الثانية من رفضهم للإيمان واستكبارهم عنه ومقاومتهم وقتالهم؛ لسه رسول الله ﷺ يرجو إسلامهم،\nما غابت عن رسول الله ﷺ رسالته وهدفه أبدا، ولو تفتكروا لما جاءه الطُّفَيْل بن عمرو الدَّوْسي بيطلب منه يدعو على قومه دَوْس لأنهم رفضوا الإسلام قال رسول الله ﷺ:\n\" اللهم أهد دوساً، وائت بهم\"\nوبعد غزوة أحد وبعد ما قريش قتلوا سبعين واحد من أصحابه قال:\n\"اللهم أهد قومي فإنهم لا يعلمون\"\nوصدق رسول الله ﷺ لما قال عن نفسه:\n\" إِنِّي لَمْ أُبْعَثْ لَعَّانًا ، وَإِنَّمَا بُعِثْتُ رَحْمَةً\"\nرجع رسول الله ﷺ من الطائف بعد أربعين يوم، ووصل إلى وادي الجعرانة، وكان عنده مهمة عظيمة، وهي مهمة تقسيم الغنائم الكتيرة دي على الجيش المنتصر\nلكن رسول الله ﷺ موزعش الغنائم أول ما رجع على طول، ده استنى كم يوم يمكن ربنا يستجيب دعوته بسرعة ويأتي أهل الطائف ويُسلموا فيرجع لهم أموالهم ونساءهم وأطفالهم،\nفلما لقاهم مجوش والناس إللي أسلموا جديد بدأوا يطلبوا توزيع الغنائم ويلحوا، \nبدأ رسول الله ﷺ بتوزيع الغنائم، وتوزيع غنائم حنين بالذات موضوع طويل،\nعشان كده هنقوله كله على بعضه المرة الجاية إن شاء الله"}, {"n": 203, "l": "الجزء 177 | احداث السنه الثامنه من الهجرة | توزيع غنائم حنين", "u": "https://www.facebook.com/groups/710210019782034/permalink/836546430481725/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وسبعة_وسبعون\n#أحداث_السنة_الثامنة_من_الهجرة\n#توزيع_غنائم_حنين\nوقفنا المرة إللي فاتت عند توزيع رسول الله ﷺ للغنائم، وقلنا إنه استنى كم يوم قبل توزيعها، استنى أكثر من عشر أيام لعل ثقيف يأتوا مسلمين فيرد عليهم رسول الله ﷺ أموالهم ونساءهم وأولادهم،\nفلما لم يأتوا ومع إلحاح الأعراب والمسلمين الجدد بتوزيع الغنائم بدأ رسول الله ﷺ بتوزيع الغنائم.\nمبدئيا كده قبل ما نشوف الغنائم اتوزعت إزاي، خلونا نفهم يعني إيه غنائم\nالغنائم هي ما يُؤخذ في الحرب قهرًا أو عنوةً، سواء ذهب أو فضة أو أموال أو غيرها، \nوالغنائم هي خَصِيصة لأمة الإسلام زي ما رسول الله ﷺ قال:\n\" أُعطيتُ خَمساً لم يُعطَهُن أحدٌ من الأنبياء قبلي، وذكر منها:《وأُحلّت ليَ الغنائم》\n يعني في الأمم السابقة لما كانوا يقاتلوا ويأخذوا غنائم من عدوّهم مكنوش بياخدوها لنفسهم، \nولكن بيجمعوها وتنزل نار من السماء تأخذ الغنائم دي زي ما قلنا قبل كده في قصة يوشع بن نون عليه  السلام،\nفالغنائم بقت حلال لأمة الإسلام، فهي نعمة من الله عز وجل وحافز قوي للمجاهد، \nفهي عوض للمجاهد عن تركه للديار وللأعمال وللأسرة وللوطن؛ وخصوصا إن أمة الإسلام هي الأمة الوحيدة المفروض عليها جهاد الطلب،\nفكان طبيعي يبقى في حافز للمجاهدين،\nوأكيد يعني الجيش إللي هتتوزع عليه الغنائم هيُقاتل بحمية وبقوة تختلف عن الجيش إللي لا يتجاوز فيه راتب الجنود دراهم معدودة\nتقسيمة الغنائم بقى في الشرع الإسلامي هي:\nأربعة أخماس الغنيمة تُوزع على أفراد الجيش المقاتل، وخُمس الغنيمة المتبقية يذهب للدولة تتصرف فيه حسب المصلحة، \nلكن للأسف في زماننا دلوقتي القادة الكبار والزعماء بيستكثروا العطاء الضخم ده للجنود، وبيحتفظوا بالأموال للدولة أو لنفسهم، وياخدوا حق الجنود \nوطبعا ده هيكون له انعكاس كبير سيء على قتال الجنود في المعارك، وعلى أداء الجنود في الحروب\nبدأ رسول الله ﷺ في توزيع الغنائم على حسب التقسيمة إللي قلناها، خلونا نحسبها بالأرقام:\nكانت الغنائم أربعة وعشرين ألف (24000) من الإبل، وأربعين ألف (40000) شاة، و أربعة آلاف(4000) أوقية من الفضة، ده غير  الستة آلاف(6000) من السبي.\nيبقى أربعة أخماس الغنيمة تساوي تسعة عشرة ألف ومائتان (19200) من الإبل، واثنان وثلاثون ألف(32000) شاة، وثلاثة آلاف ومائتان(3200) أوقية من الفضة، وأربعة آلاف وثمانمائة(4800) من السبي، فهذه الغنائم توزع على (12000) مقاتل.\nوكانوا يقيّمون الجمل الواحد بعشرة من الشّياه، يعني كل واحد من أفراد الجيش هيأخد إما جَملين، وإما عشرين من الشّيَاه،\nأما تقسيم الفضة فكل واحد هياخد رُبع أُوقية من الفضة،\nوبالنسبة للسبي فبيتقسم بمعرفة الزعيم أو الإمام أو رئيس الدولة، وبما أن السبي (4800) وعدد الجيش (12000) ففي ناس هتاخد وناس لأ، \nفكان رسول الله ﷺ أحيانا بيعمل قُرعة بين الصحابة مين هيطلع من نصيبه السبي، وساعات كان بيعوضهم بالمال،\nفالقاعدة إللي تحكم هي: التقسيم بالتساوي بالنسبة لأربعة أخماس الغنائم بين المقاتلين\nأما بالنسبة للخُمس الباقي، فالمال ده هو مال الدولة، ورسول الله ﷺ كقائد يوجهه في الوجه الأصلح للدولة،\nيعني ممكن يشترى بالمال ده سلاح، \nأو يفتدى به الأسرى، أو تكون منه الهِبَات لأهل البأس والقوة في الحرب، أو ممكن تُعطى منه رواتب وأجور، أو يدخل في مشروعات الدولة المختلفة،\nالمهم إن القائد هينفق المال ده في الوجه الأصلح للدولة\n☆طيب إيه بقى الوجه الأصلح للدولة في الوقت ده\nشوفوا،\nرسول الله ﷺ عارف إن في جيشه إللي متردد جداً في الإسلام،\nوفي إللي دخل الإسلام عشان خايف من قوته، أو دخل الإسلام رغبةً في الغنائم،\nوفي منهم إللي كان سيداً مطاعاً في قومه محدش في العرب يقدر يمشّي كلمته عليه، فبقى دلوقتي تابع لرسول الله ﷺ،\nومنهم إللي لو أمر قبيلته بالردة ومحاربة المسلمين هيعملوا كده فعلا،\nفالناس دي لسه الإيمان مكنش ملأ قلوبهم واستقر فيه ولا اقتنعوا تماما بالإسلام، ورسول الله ﷺ كان عارف كل ده، عشان كده كان لازم يكون في حل عشان يتألف قلوب الناس دي ويُثَبّت قلوبهم على الإسلام\nفكان الحل إن رسول الله ﷺ يراضيهم بعطاء سخي عظيم،\nفساعتها هيحسوا إن حالتهم المادية استقرت، وإن أموالهم كثُرَت، وإن وضعهم الاجتماعي تحسّن بعد انتمائهم للدولة الإسلامية،\nوبالتالي هيحبوا الدولة إللي حققت لهم الرخاء ده، ويحاولوا بكل طاقتهم إنهم يدعموا الدولة دي عشان وضعهم يستمر في التحسّن، \nوبكده يَأْمن رسول الله ﷺ جانبهم وإنهم مينقلبوش للكفر مرة تانية، ولا يأثروا على قومهم ويرجعوهم للكفر تاني؛\nلأن النظام القَبلي المترسخ في الجزيرة العربية بقاله قرون يخلي قائد القبيلة له الكلمة العليا المطلقة في قبيلته؛ \nفعشان كده رسول الله ﷺ كان عايز يشتري رضا الزعماء واستقرارهم بالمال\nوبالتالي هيكون لهم تأثير إيجابي على أَتْباعهم من القبائل المختلفة، \nيعني يا جماعة باختصار رسول الله ﷺ بيشتري استقرار الدولة الإسلامية؛ لأن مكنش في وقت لتربية المسلمين الجدد دول تربية إيمانية زي ما المهاجرين والأنصار اتربوا على مدار واحد وعشرين سنة، فكان لازم حل سريع\nفبدأ بقى رسول الله ﷺ يُعطي زعماء العرب وبعض إللي لهم مكانة من إللي أسلموا حديثا أموال زيادة من الخُمس المملوك للدولة، \nوالخُمس ده مكنش عدد بسيط يعني، ده كان كتير، يعني الخمس ده كان أربعة آلاف وثمانمائة(4800) من الإبل، وثمانية آلاف(8000) شاه، وثمانمائة(800) أوقية من لفضة، وألف ومئاتان (1200) من السبي،\nوكان عدد المؤلفة قلوبهم حوالي عشرين رجل، زي أبو سفيان وعيينة بن حصن، وحكيم بن حزام وعكرمة بن أبي جهل وغيرهم،\nفكان رسول الله ﷺ يُعطي الواحد منهم مائة بعير، يعني مائة جمل، وأحيانا خمسين،\nواحنا قلنا إن الجمل الواحد ثمنه من ثمانية وأربعين ألف(48000) لستة وخمسين ألف(56000) جنيه،\nيعني على أقل تقدير رسول الله ﷺ كان بيعطي للواحد من الزعماء دول ما يساوي حوالي خمسة مليون جنيه\nده غير الفضة والأغنام، يعني أموال كتيرة جدا\n☆طيب في هنا سؤال مهم:\nهو مش الإيمان إللي بيكون سببه حب المال بيبقى إيمان ضعيف\nأيوة بيبقى إيمان ضعيف، لكن ده بيبقى في البداية بس،\nلكن لما الواحد بيتربى على الإيمان التربية الصحيحة يبدأ الإيمان في الرسوخ تدريجياً لحد ما يبقى الإيمان أغلى عنده من المال، وهو ده إللي حصل فعلا،\nحتى إن أنس بن مالك رضي الله عنه قال عن الموقف ده:\n\"إنْ كانَ الرَّجُلُ ليُسْلِمُ مَا يُريدُ إلاّ الدُّنْيَا، فَمَا يُسْلِمُ حَتَّى يَكُونَ الإسلام أحَبّ إليه مِنَ الدُّنْيَا وَمَا عَليها\"\nيعني بيقول إن الواحد في الوقت ده كان بُيسلم عشان أجر الدنيا من الغنائم لكن أول ما يستقر الإسلام في قلبه بيكون الإسلام أحب إليه من الدنيا باللي فيها،\nوهو ده فعلا إللي حصل مع أبي سفيان وحكيم بن حزام وصفوان أمية وعكرمة بن أبي جهل وغيرهم،\nكانوا بينفقوا أموالهم في سبيل الله ويجاهدوا وكانوا بيمشوا في كل طريق فيه مرضاة لله\nفالهدف من تأليف القلوب بالمال هو الإغراء والتشجيع في البداية لحد ما القلب يستقر فيه الإيمان ويذوق حلاوته،\nفساعتها مش هيبقى محتاج حاجة تشجعه من أمور الدنيا وهيبقى همه الآخرة\nطبعا يا جماعة التصرف إللي عمله رسول الله ﷺ هيكون له أثر سلبي على بعض المسلمين إللي اجتهدوا في القتال وثبتوا مع رسول الله ﷺ وإللي فعلا يستحقوا المكافأة، \nلأ وهنشوف كمان إللي اعترض بصراحة كده على رسول الله ﷺ واتهمه بعدم العدل\nلكن رسول الله ﷺ كان همه استقرار دولة الإسلام؛ لأن لو حصل اضطراب في الدولة الإسلامية الكل هيعاني من الأزمات إللي هتحصل،\nفمفيش مشكلة من تحمّل بعض الضرر النفسي في مقابل استقرار دولة الإسلام، يعني رسول الله ﷺ كان بيطبق قاعدة:\n《دَفع أكبَر الضّرَرِين، وجَلبْ أكبر المَنْفَعتِين》\nقبل ما نعرف بقى المواقف إللي حصلت أثناء توزيع الغنائم وردود أفعال الصحابة المختلفة عندنا نقطة محتاجة تتوضح وهي:\nإن الفقهاء اختلفوا في طريقة توزيع رسول الله ﷺ لغنائم حنين،\nيعني رسول الله ﷺ كان بيوزع الغنائم في كل المعارك السابقة بحسب التقسيمة إللي قلناها في البداية،\nإللي هي أربعة أخماس على أفراد الجيش المقاتل والخمس الباقي للدولة يتصرف فيه رسول الله ﷺ على حسب المصلحة، ولحد هنا الفُقَهاء متفقين،\nلكن الاختلاف بينهم حصل في توزيع غنائم حنين،\n◇فريق منهم قال:\nإن رسول الله ﷺ وزّع الغنائم كووولها على المُؤلّفة قلوبهم فقط.\n☆والمؤلفة قلوبهم دول هم إللي أسلموا حديثاً وكان إسلامهم ضعيف سواء من أهل مكة الطّلقاء، أو من إللي أسلموا من الأعراب قبل فتح مكة على طول،\nأو المشركين من الزعماء إللي عندهم استعداد نفسي في إعادة النظر في الدعوة بس محتاجين زقة زي ما بنقول\n◇الفريق التاني قال:\nإن رسول الله ﷺ وزّع أربعة أخماس الغنيمة على الجيش بكامله كالعادة، وبعدين أعطى المؤلفة قلوبهم من الخمس المتبقي المملوك للدولة، يعني أخدوا زيادة عن باقي الجيش زي ما شرحنا كده\nوالرأي الثاني ده هو الأصح\nطيب ليه\nلأن الرأي ده يتفق مع الشرع والعقل والنقل، وعندنا أدلة على كده، نركز بقى عشان الموضوع ده مهم\n◇الدليل الأول: \n الغنائم مش مِلْك شخصي لرسول الله ﷺ عشان يوزعها بطريقة تخالف التوزيع الشرعي، إلا طبعا لو الوحي جاء باستثناء في التوزيع ده، لكن ده محصلش، فأربع أخماس الغنائم ملك للجيش، ولا تُؤخذ منه إلا باستئذان خاص منه.\n◇الدليل الثاني: \nلو كان في تغيير في قسمة الغنائم كان الطبيعي إن رسول الله ﷺ يقول إن التقسيمة دي تقسيمة خاصة ملهاش دعوة بالتقسيمة الأساسية؛ عشان محدش يعتقد إن إللي رسول الله ﷺ عمله ده نَسَخ التقسيم السابق للغنائم، \nوخصوصا إن معركة حُنين هي آخر موقعة حربية مع العرب، حتى غزوة تبوك إللي هتحصل بعدين محصلش فيها قتال، ومكنش فيها غنائم، فكان لازم يكون في توضيح من رسول الله ﷺ لو كان فعلا خالف التقسيمة الشرعية للغنائم إللي قلنا عليها في البداية\n◇ الدليل الثالث:\nرسول الله ﷺ لما بدأ بتوزيع الغنائم؛ الناس قعدوا يتزاحموا عليه ويطلبوا نصيبهم من الغنائم لدرجة إنهم أخذوا رداء رسول الله ﷺ في الزحمة، كله عايز يلحق ياخد من الغنائم،\nفهنا عشان رسول الله ﷺ يطمنهم مِسك بإيده وبرة أو شعرة من شعر جمل ورفعها وقال لهم:\n\" أيها الناس إنه والله ليس لِي من فَيْئِكم ولا هذه الوبرة إلا الخُمْس والخمس مردود عليكم\"\nيعني بيقولهم أنا لا أملك من الغنائم حتى الشعرة دي، كل إللي أملكه هو الخُمس، وحتى الخمس ده هيرجع لكم انتم على حسب مصلحتكم،\nفرسول الله ﷺ بيصرّح هنا أهه إنه لا يملك في يوم حنين إلا الخمس فقط من الغنائم،\nفعلى أي أساس بقى قيل إنه وزع الغنائم على المؤلفة قلوبهم فقط\n◇ الدليل الرابع:\nلو بصينا كده على إللي اتوزع عليهم الغنائم هنلاقي إن من المستحيل إن رسول الله ﷺ قسّم كل الغنائم دي على المؤلفة قلوبهم فقط،\nفعدد إللي رسول الله ﷺ أعطاهم العطاء السخي ده لا يزيدون في أي كتاب من كتب السيرة على عشرين رجلاً،\nولو جمعنا الأسماء من الكتب المختلفة ممكن نوصل إلى أربعين أو خمسين رجلاً بالكتير أوي يعني\nفخلونا كده نحسبها،\nإذا كان رسول الله ﷺ بيعطي الناس مائة من الإبل فعطاؤه لأربعين رجلاً هيبلغ أربعة آلاف بعير فقط، مع إنه كان بيعطي بعضهم خمسين بس مش مائة،\nفهيكون العدد أقل من أربعة آلاف أو أقل من خمسة آلاف بعير، \nطيب احنا عندنا أربعة آلاف بعير أهم، فين بقى باقي الأربعة وعشرين ألف بعير إللي همّ غنائم المسلمين من الإبل\nده طبعا غير الأغنام والذهب والفضة والسّبْي،\nولم يَرِد إن رسول الله ﷺ أعطى أرقام كبيرة كمائة بعير أو خمسين بعير إلا للمجموعة دي فقط من المؤلفة قلوبهم،\nفكده واضح أهه إن رسول الله ﷺ وزّع أربع أخماس الغنائم على الجيش\n◇الدليل الخامس: \nهل أفراد القبائل من الأعراب ومن قريش كانوا هيرضوا إن الزعماء بس همّ إللي ياخدوا من الغنائم؟\nولّا هيبقوا عايزين همّ كمان نصيبهم من الغنائم ولو حاجة بسيطة\nكل القلوب كانت تهفو إلى الغنيمة، وكل الناس محتاجين إلى تأليف قلوبهم،\nومعظم المسلمين إللي دخلوا في الإسلام بعد صلح الحديبية وبعد فتح خيبر محتاجين إلى تأليف لقلوبهم، \nومحدش هيترفع منهم عن الغنيمة دي إلا القليل، زي: خالد بن الوليد ، عمرو بن العاص ، وعثمان بن طلحة ، والعباس ، وغيرهم من الأفراد المعدودين،\nأما الباقي فهيحتاج إلى تأليف، ودليل كده إن رسول الله ﷺ  لما حصلت الهزيمة في بداية المعركة لم ينادِ على المسلمين إللي أسلموا قبل الفتح؛ لأنه عارف إن منهم ما أسلم إلا رغباً أو رهباً، \nلكن رسول الله ﷺ قصد بالنداء أصحاب الشجرة أهل الحديبية ودول كانوا ألف وأربعمائة فقط،\nيعني عشان يُرضي المسلمين الجدد؛ يبقى هيعطي عشرة آلاف وستمائة(10600) مقاتل من الغنيمة، وكده يتبقى الألف وأربعمائة(1400) إللي همّ أصحاب الشجرة،\nفإذا كان رسول الله ﷺ ينوي إعطاء (10600) من الغنيمة يبقى هيعجز  إنه يعطي(1400) الباقين؟ \nكلام غريب طبعا لا يُقبل، وخاصة إن همّ إللي أدوا ما عليهم، وهمّ إللي دافعوا وكافحوا وبذلوا الجهد، وردوا كيد المشركين، فإعطاء (1400) لا يؤثر مطلقاً في إعطاء 10600).\nفمفيش أي داع لحرمانهم من الغنيمة الرئيسية الشرعية المُستحقة وهي أربعة أخماس الغنيمة الكلية\n☆طبعا في حديث صحيح عن رسول الله ﷺ إنه لم يعطِ الأنصار شيئا وحصل أزمة بسبب كده،\nوده معناه إن رسول الله ﷺ لم يُقسم الغنائم التقسيم إللي قلنا عليه، إللي هو أربعة أخماس الغنائم للجيش،\nلكن الكلام ده هنوضحه بالتفصيل بعدين إن شاء الله \nنرجع بقى ونشوف الناس إللي رسول الله ﷺ أعطى لهم العطاء الزيادة،\nأول واحد من الزعماء إللي رسول الله ﷺ تأَلّف قلبه وأعطاله المال كان أبو سفيان بن حرب رضي الله عنه،\nجاء لرسول الله ﷺ وهو في وادي الجعرانة، ولما شاف أبو سفيان الغنائم الهائلة دي قال: يا رسول الله، أصبحت أكثر قريش مالاً \nيعني بقيت أغنى واحد فينا، يعني بيلمّح إن في أموال كتير، وعايز منها، فرسول الله ﷺ تبسم له ومتكلمش،\nفلما لقى التلميح مش نافع راح قايل لرسول الله ﷺ صراحة كده: أعطني يا رسول الله من هذا المال!\nرسول الله ﷺ كان مقدر المعاناة إللي كان حاسس بيها أبو سفيان بسبب المواقف إللي مر بيها الشهور إللي فاتت من قبل فتح مكة، \nوإيمانه إللي كان في ظروف قاسية وكان لسه متزعزع، ده غير إنه خلاص مش هيبقى زعيم مكة وفي واحد بداله هيمسك زعامة مكة وهنتكلم عنه في وقتها إن شاء الله،\nفرسول الله ﷺ مقدّر كل ده وعايز يُثبّت قلبه على الإسلام، فقال لبلال رضي الله عنه:\n\"يا بلال زِنْ لأبي سفيان أربعين أُوقية من فضة، وأَعطهِ مائة من الإبل\"\nواخدين بالكم مين بيدي مين\nبلال العبد إللي كان يُباع ويُشترى وبيُعذب في مكة دلوقتي بقى هو المُقرب من زعيم الدولة وهو إللي بيعطي ده وده من الزعماء السابقين\n\"وَتِلْكَ الْأَيَّامُ نُدَاوِلُهَا بَيْنَ النَّاسِ\"\nأبو سفيان طبعا مكنش مصدق نفسه\nحوالي كيلو ونص فضة ومائة بعير بقت مِلكه في لحظة، والمائة بعير ده هو نفس رقم المكافأة إللي قريش أعلنت عنها للي يأتي برسول الله ﷺ حياً أو ميتاً يوم الهجرة فاكرين\nفسبحان مُبدل الأحوال\nأبو سفيان شاف العطاء إللي رسول الله ﷺ أعطاه له فطلب لأبنائه يزيد ومعاوية، فقال لرسول الله ﷺ:\nوابني يزيد يا رسول الله\nفقال رسول الله ﷺ لبلال:\n\"زِنْ له يا بلال أربعين أُوقية من فضة، وأَعطهِ مائة من الإبل\"\nفقال له أبو سفيان:\nوابني معاوية يا رسول الله\nفقال رسول الله ﷺ لبلال:\n\"زِنْ له يا بلال أربعين أُوقية من فضة، وأَعطهِ مائة من الإبل\"\nويزيد ومعاوية كانا مسلمين،\nفلما أبو سفيان شاف رسول الله ﷺ بيعطي العطاء ده بدون أي نقاش وبكل سهولة كده ذُهل\nوقال لرسول الله ﷺ:\n\"إِنَّكَ لَكَرِيمٌ ، فِدَاكَ أَبِي وَأُمِّي، وَاللَّهِ لَقَدْ حَارَبْتُكَ فَنِعْمَ الْمُحَارِبُ كُنْتَ، ثُمَّ سَالَمْتُكَ فَنِعْمَ الْمُسَالِمُ أَنْتَ، جَزَاكَ اللَّهُ خَيْرًا\"\nتحسوا بصدق في كل كلمة قالها سبحان الله، أبو سفيان اختصر حياته كلها مع رسول الله ﷺ في الكلمتين دول\nإيه إللي غيّر رجل كان بيشُك في نبوة رسول الله ﷺ إلى رجل مؤمن مادح لرسول الله ﷺ؟\nإيه إللي ثبّته بعد ما كان متردد؟ \nإيه إللي أسعده بعد ما كان حزين بعد تغير الأحوال في مكة؟\nمش همّ الثلاثمائة من الإبل والمائة والعشرين أوقية من الفضة؟\nطيب وهي تيجي إيه قيمة الأموال دي جنب هداية إنسان؟ وإيه هي قيمة الأموال جنب استقرار الدولة الإسلامية؟\nوتيجي إيه الأموال دي جنب تأليف قلوب بني أمية وتثبيت  أهل مكة على الإيمان؟\nصحيح إن المال حلو ومهم، لكنه يتصاغر جدا جنب المعاني دي\nوهي دي كانت نظرة رسول الله ﷺ للأمور، عشان كده كان ﷺ يُعطي بلا حساب، \nكان يُعطي عطاء من لا يَخشى الفقر، كان يُعطي وكأن المال لا ينتهي، والعطاء موقفش عند أبي سفيان رضي الله عنه  وابنيْه يزيد ومعاوية، لكنه أعطى غيرهم وإللي هنعرف قصتهم المرة الجاية إن شاء الله"}, {"n": 204, "l": "الجزء 178 | احداث السنه الثامنه من الهجرة | موقف الأنصار من توزيع غنائم حنين", "u": "https://www.facebook.com/groups/710210019782034/permalink/836546797148355/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وثمانية_وسبعون\n#أحداث_السنة_الثامنة_من_الهجرة\n#موقف_الأنصار_من_توزيع_غنائم_حنين\nاتكلمنا المرة إللي فاتت عن طريقة توزيع رسول الله ﷺ للغنائم، وشوفنا إزاي أعطى لأبي سفيان عطاء عظيم من الغنائم هو وابنيه يزيد ومعاوية رضي الله عنهم جميعا.\nرسول الله ﷺ كمّل توزيع الغنائم وإعطاء المؤلفة قلوبهم،\nفجاء حكيم بن حزام لرسول الله ﷺ،\nولو تفتكروا حكيم بن حزام ده يبقى ابن أخت خديجة بنت خويلد رضي الله عنها،\nيعني رسول الله ﷺ يبقى زوج عمته، وكان حكيم بيساعد المسلمين لما كانوا محاصرين في شِعب أبي طالب، وأسلم حكيم بعد فتح مكة،\nحصل بقى حوار بين حكيم و بين رسول الله ﷺ مليان عِبر\nوإللي حكي الحوار ده حكيم بن حزام نفسه، بيقول:\n\"سألت رسول الله ﷺ فأعطانِ\"\nيعني حكيم طلب من رسول الله ﷺ يعطيه من الغنائم، فأعطاه رسول الله ﷺ مائة من الإبل،\nوبعدين حكيم سأله تاني إنه يعطيه من الغنائم، فأعطاه رسول الله ﷺ مائة ثانية من الإبل،\nفسأله حكيم مرة ثالثة إنه يعطيه من الغنائم، فأعطاه رسول الله ﷺ مائة ثالثة، يعني واخد خمسة عشر مليون جنيه وهو واقف كده من رسول الله ﷺ \nهنا بقى رسول الله ﷺ كان عايز يعلم حكيم بن حزام درس تربوي مهم، قال له: \n《يا حكيمُ، إنَّ هذا المالَ خَضِرَةٌ حُلوَةٌ، فمَنْ أخَذَهُ بسَخَاوة نفْسٍ بُورِكَ لَهُ فيه،\nومَنْ أَخَذَهُ بإشْرافِ نَفْسٍ لم يُبَارك له فيه، وكان كالذي يأكلُ ولا يَشْبَعُ، اليدُ العليا خيرٌ من اليد السُّفلى》\nهنا رسول الله ﷺ بيتكلم عن الدنيا بصفة عامة عشان كده قال حلوةٌ خَضِرة ومقلش حلوٌ خَضِر،\nوالمال جزء من الدنيا، فرسول الله ﷺ بيشبه المال بالخضار عشان يقوله إن المال سريع الزوال زي ما الزرع الأخضر بيذبل بسرعة\nفاللي بياخد المال من غير ما يكون عنده شَرَه ومن غير إلحاح منه ومن غير ما يضايق المُعطي ولا يحرجه؛ ربنا بيبارك له في المال ده،\nأما إللي بياخده بطمع وبيبقى عايز زيادة ويقعد يطلب ويطلب؛ ربنا مش بيبارك له في المال ده، وبيبقى عامل زي إللي بياكل ومش بيشبع، \nوالإنسان إللي بيعطي وبيُنفق في سبيل السبيل الله أحسن من إللي بيسأل الناس وياخد أموالهم\nلما سمع حكيم بن حزام كلام رسول الله ﷺ اتعلم الدرس وفهمه كويس، ورجع المائة الثانية والثالثة وأخذ الأولى فقط، وقال لرسول الله ﷺ:\n\"يا رسولَ الله، والذي بعثكَ بالحقِّ لا أرْزَأُ أحدًا بعدَكَ شيئًا حتَّى أفارقَ الدنيا\"\nيعني مش هاخد أي مال من أي حد لحد ما أموت \nوفعلا يا جماعة حكيم بن حزام حافظ على عهده ده مع رسول الله ﷺ لحد ما مات،\nفكان أبو بكر الصديق في خلافته يدعوه عشان ياخد نصيبه من الغنيمة وهو كان يرفض ياخدها،\nوكان عمر في خلافته يدعوه عشان ياخد نصيبه فكان بيرفض، وكان عمر بيقول للناس :\n\"إني أُشْهدُكُم يا مَعْشَرَ المسلمين على حكيم، أنِّي أَعْرِضُ عليه حَقَّهُ من هذا الفَيْء فيأبى أن يأْخُذَه\"\nيعني اشهدوا إني أعطيه نصيبه وحقه من الغنائم وهو إللي بيرفض ياخده مش أنا إللي منعته حقه،\nواستمر كده لحد ما مات رضي الله عنه ولم يأخذ مال من أحد من المسلمين\nأكمل رسول الله ﷺ توزيع الغنائم، وبدأ يعطى الناس إللي حاسس منهم إن لسه في قلوبهم بعض الكره والحقد على الإسلام والمسلمين،\nفأعطى رسول الله ﷺ سهيل بن عمرو مائة من الإبل ومائة أوقية من الفضة، وكان أسلم بعد غزوة حنين وبعد حصار الطائف والعودة لوادي الجعرانة،\nوسهيل يا جماعة بعد ما أسلم كان أكثر صلاةً وصومًا وصَدقة من كل كُبراء قريش إللي تأخر إسلامهم،\nوكان كثير البكاء رقيقًا عند قراءة القرآن،\nسبحان مقلب القلوب\nوأعطى رسول الله ﷺ الحارث بن هشام أخو أبو جهل عشان يلين قلبه ويهوّن عليه مصابه في مقتل أخيه، وعشان يتألف قلوب بني مخزوم،\nوأعطى النُّضَير بن الحارث أخو النّضر بن الحارث شيطان قريش المعروف، \nإللي كان من أشد أعداء رسول الله ﷺ،\nوإللي كان بيقول هو محمد أحسن مني في إيه، أنا بحكي أساطير ومحمد بيحكي بأساطير،\nفأعطاه رسول الله ﷺ مائة ناقة ومائة أوقية من الفضة عشان يتألف قلبه ويتألف قلوب قبيلته،\nبعد ما رسول الله ﷺ أعطى زعماء مكة، بدأ يعطي بعض زعماء قبائل العرب، عشان يضمن ولاءهم وانتماءهم للدولة الإسلامية،\n فأعطى عيينة بن حصن زعيم قبيلة بني فزارة، مائة من الإبل، والرجل ده كان غليظا جداً وسيئ الخلق\nفرسول الله ﷺ اشتراه بالمال في الموقف ده، عشان ميعملش فتنة بين الناس، وأخلاقه متغيرتش كتير بعد إسلامه،\nحتى إنه بعد موت رسول الله ﷺ ارتد وقاتل ضد المسلمين، وبعدين رجع وأسلم مرة تانية في خلافة أبي بكر بعد ما أسره خالد بن الوليد وهو بيحارب المرتدين وأرسله للمدينة لأبي بكر رضي الله عنه.\nوكمان رسول الله ﷺ أعطى زعيم بني تميم وكان اسمه الأقرع بن حابس وكان من غِلاظ الطباع، وحديث الإسلام، وقبيلته بنو تميم قبيلة قوية فأعطاه مائة من الإبل عشان يتألف قلبه ويتألف قبيلته\nمين بقى إللي شايف الأموال بتتوزع هنا وهنا وواقف متحسر على حاله وشايف إنه ملوش نصيب في الغنائم دي \nصفوان بن أمية\nصفوان ساعتها كان لسه على الشرك، وكان خرج مع المسلمين عشان رسول الله ﷺ أخد منه دروع وأسلحة بالأجرة وكان مسؤول عن نقلها لأرض المعركة،\nوكان رسول الله ﷺ مديله مهلة أربعة شهور يفكر في الإسلام،\nفدلوقتي هو شايف الغنائم بتتوزع على المسلمين أو يعني إللي مظهرين الإسلام،\nوهو لأنه مشرك كان عارف إن رسول الله ﷺ مش هيديله حاجة،\nلكن حصل بقى إللي صفوان مكنش متوقعه\nرسول الله ﷺ نادى صفوان بن أمية وأعطاه مائة من الإبل، زي ما أعطى زعماء المسلمين من أهل مكة\nوبعد ما أعطاه رسول الله ﷺ الإبل نظر صفوان إلى وادِ في حُنين فيه إبل كثيرة وشِياه كثيرة، \nفظهرت عليه علامات الانبهار من كمية الأنعام، فقال له ﷺ: \nأبَا وهب، يعجبك هذا الشأن؟\nيعني عجبتك الأغنام والإبل دي؟ \nفقال صفوان بكل صراحة : نعم.\nفقال رسول الله ﷺ بكل سهولة: هو لك وما فيه\nوكأنه بيتنازل عن جمل أو جملين ﷺ\nفاتصدم صفوان بن أمية و ذُهِل من تصرف رسول الله ﷺ العجيب ده\nمين إللي يتنازل عن كمية الأموال دي كلها بالسهولة دي\nفصفوان مقدرش يمسك نفسه وقال لرسول الله ﷺ:\nما طَابت نفسُ أحدٍ بمثلِ هذا إلا نفسُ نبي\nأشهد أنه لا إله إلا الله، وأن محمداً عبده ورسوله\nيعني محدش يقدر يتنازل عن كل الأموال دي بطيب نفس كده إلا نبي،\nودخل صفوان في الإسلام رضي الله عنه \nرسول الله ﷺ يا جماعة أعطى لصفوان من خُمس الغنائم وهو مشرك عادي وده يجوز؛ لأن الخُمس ده يُصرف في مصالح المسلمين، ومن مصلحة المسلمين إن واحد زي صفوان بن أمية يدخل في الإسلام\nيقول صفوان وهو بيحكي عن نفسه:\n\"والله لقد أعطاني رسول الله ﷺ ما أعطاني وإنه لأبغض الناس إليّ، \nفما برح يعطيني حتى إنه لأحب الناس إليّ\"\nيعني صفوان كان بيكره رسول الله ﷺ لكن لما أعطاه وتألف قلبه بقى أحب الناس إلى صفوان،\nفبشوية إبل و شِياه إما تؤكل أو تموت أُضيفت للمسلمين قوة الزعيم المكي المشهور صفوان بن أمية واللي حَسُن إسلامه بعد كده، وبقى من المجاهدين في سبيل الله،\nكل الدنيا هتفنى لكن إللي لن يزول هو نعيم الجنة.\nكم واحد من البشر سيذوق نعيم الجنة ويخلد فيه؛ لأن رسول الله ﷺ أعطاه مجموعة من الإبل والشياه؟ \nمش ده فِهْم راقي من رسول الله ﷺ لحقيقة الدنيا وحقيقة الآخرة، وحقيقة الغنائم وحقيقة البشر؟!\nرسول الله ﷺ هانت عليه الدنيا كلها وكان بيعطيها للناس بدون تردد؛ لأن الدنيا عنده لا تساوي جناح بعوضة.\nوده مكنش كلام نظري فلسفي وخلاص،\nده كان واقع في حياة رسول الله ﷺ وحياة الصحابة، وكان الواقع ده ظاهر جدا في توزيع غنائم حنين؛ حيث أن رسول الله ﷺ أعطى ما لم يُعطِ أحد من العالمين،\nمفيش حد على وجه الأرض كان بيعطي الناس كده عن طيب نفس زي رسول الله ﷺ،\nتخيلوا إن رسول الله ﷺ لم يتبقَ له ما يعوّض به فقر السنين وتعب العمر، وهو ساعتها كان عدى الستين من عمره، ولم يحتفظ لنفسه بشيء ﷺ وقعد يوزع هنا وهناك،\nوحاصره الأعراب الجُفاة وتزاحموا عليه وقعدوا يطلبوا منه المال والأنعام وفضل يرجع لورا لحد ما اضطروه إلى شجرة ونزعوا رداءه، \nعملوا معاه كده وهو الزعيم المنتصر والقائد الأعلى والرسول الكريم ﷺ\nفقال لهم رسول الله ﷺ في أدب ورفق ولين يليق به كنبي: \"يا أَيُّها الناسُ رُدُّوا عَلَيَّ رِدائي، \nفَوَاللهِ لو أن لي بعددِ شجرِ تِهامةَ نَعَمًا لقَسَمْتُه عليكم ،ثم لا تَلْقَوْنِي بخيلًا ، ولا جَبانًا، ولا كَذُوبًا\"\nوصدق رسول الله ﷺ، فهو ما كان بخيلاً ولا جباناً ولا كذاباً\nطبعا مش كل الناس كانت فاهمة وجهة نظر رسول الله ﷺ ولا فاهمين أبعاد إللي رسول الله ﷺ عمله ده،\nوكان في ردات فعل مختلفة من المسلمين،\nزي واحد من الأعراب، لما شاف رسول الله ﷺ بيوزع الغنائم على المؤلفة قلوبهم قال لرسول الله ﷺ:\n\"وَاللهِ إِنَّ هَذِهِ قِسْمَةٌ مَا عُدِلَ فِيهَا، وَمَا أُرِيدَ فِيهَا وَجْهُ اللهِ\"\nيعني قسمة الغنائم دي قسمة ظالمة وإللي رسول الله ﷺ عمله ده مكنش هدفه ابتغاء مرضاة الله، والعياذ بالله\nالكلمة دي يا جماعة كلمة كفرية،\nيعني هو بيُنسب لرسول اللهﷺ عدم العدل وإن رسول الله ﷺ لم يُرِد بالقسمة وجه الله،\nوطبعا هو مكنش فاهم حاجة ولا عارف وجهة نظر رسول الله ﷺ إيه ولا إيه الهدف من توزيع رسول الله ﷺ للخمس من الغنائم بالطريقة دي،\nوالجهل ده هو إللي بيوقع صاحبه في الهلاك والعياذ بالله\nوأنا بقولكم إن لو ناس من عصرنا دلوقتي كانوا موجودين على عهد رسول الله ﷺ وشافوا إللي رسول الله ﷺ عمله ده كانوا قالوا أكتر من كده\nده دلوقتي بيتعدوا على رسول الله ﷺ وبيتهموه اتهامات باطلة مع إن كل حاجة واضحة قصادهم\nالمهم،\nلما الكلام وصل لرسول الله ﷺ تغير وجهه وقال: \nفَمَنْ يَعْدِلُ إِذَا لَمْ يَعْدِلِ اللهُ وَرَسُولُهُ؟\nوفعلا ده صح، لو الله الحكم العدل لم يعدل ورسول الله ﷺ إللي يأتيه الوحي من الله وربنا بيقره على إللي بيعمله لم يعدل، مين بقى إللي هيعدل \nوالكلمة إللي اتقالت عنه ﷺ دي مكنتش مثلا في بداية الدعوة فممكن تكون هينة على رسول الله ﷺ بحيث إن الناس لسه متعرفوش،\nلأ، ده كان بعد ما ربنا مكّن له وانتصر على أعداءه، وبعد ما عُرِف صدقه، \nوبعد ما ربنا أظهر آيات رسول الله ﷺ في الآفاق وعرفوا صدق نبوته، \nفبعد كل ده يُقال: هذه القسمة لم يعدل فيها، ولم يُرِد بها وجه الله\nفكانت الكلمة شديدة جدا على رسول الله ﷺ\nفقال رسول الله ﷺ :\n\"يَرْحَمُ اللهُ مُوسَى، قَدْ أُوذِيَ بِأَكْثَرَ مِنْ هَذَا فَصَبَر\"\nيعني هنا رسول الله ﷺ عشان يهوّن على نفسه الأذى والاتهام الباطل إللي اتعرّض له تذكر الابتلاءات إللي تعرض لها موسى عليه السلام وصبْره عليها،\nمع إن رسول الله ﷺ هو أشد الأنبياء ابتلاء على الإطلاق\nلكن كان ده من تواضعه ﷺ.\n☆وطبعا ده يعلمنا إننا نصبر ونحتسب لما حد من الناس يتهمنا بشيء باطل واحنا مش كده،\nوعلى طول نفتكر رسول الله ﷺ والأذى إللي اتعرض له عشان نهون على نفسنا،\nزي ما رسول الله ﷺ افتكر إللي حصل مع موسى عليه السلام وهون بيه على نفسه \nومنستغربش بقى لما حد يطعن على العلماء الربانيين ويتهموهم بالباطل وهمّ مش عارفين حاجة عنهم\nواحنا لازم ناخد بالنا إن أعداء الإسلام بيحاولوا بكل الطرق إنهم يشوّهوا صورة العلماء، \nعارفين ليه\nلأنهم إذا قدحوا في العلماء وشوهوا صورتهم عند الناس؛    هتسقط أقوال العلماء عند الناس ومش هيبقى لكلامهم أي تأثير\nومش هيتبقى للناس حد يقودهم بكتاب الله؛\nلأن العلماء هم إللي بيحملوا لواء الإسلام، فإذا سقطت الثقة بأقوالهم؛ سقط لواء الإسلام، وبقى في ضرر على الأمة الإسلامية،\nوطبعا عشان الصورة تكمل، يتحط بقى مكان العلماء دول ناس جديدة ظاهرهم العلم ويتلمعوا ويتمدح فيهم، وتبدأ الناس تسمع لهم،\nوساعتها بقى يدلّسوا على الناس دينهم ويُحلّوا لهم الحرام ويزينوا لهم البدع والشركيات،\nزي ما رسول الله ﷺ وصفهم بالضبط:\n\" هم مِن جِلدتنا ويتكلّمون بألسنتنا\"\nوالناس بقى تقع في الأخطاء دي لحد ما يتشربوها ولما حد ييجي ينصحهم بالصح يستنكروا ويتهموا العلماء بالتشدد وميسمعوش لكلامهم أصلا\nوهمّ دول إللي رسول الله ﷺ قال عنهم:\n\"دعاة على أبواب جهنم من أجابهم إليها قذفوه فيها\"\nونظرة سريعة كده على الواقع بتاعنا يا جماعة خلال السنين إللي فاتت وإللي بيحصل حاليا وانتم هتتأكدوا من كلامي\nوزي ما قلنا قبل كده في قصص الأنبياء إن الشيطان باله طويييل أوي ومش بيزهق، \nهو بيحط البذرة ويفضل يرعاها ومعندوش مشكلة إنه يحصد الزرع بتاعه في الجيل إللي بعده\nوإللي كان عايش من خمسة وعشرين وشاف زمننا دلوقتي هيعرف التغير الجذري إللي حصل في الناس،\nوإللي بيقرأ كلامي دلوقتي هيشوف التغير إللي هيحصل للناس كمان خمسة وعشرين سنة قدام\nفعلى الأقل يا جماعة نحمي نفسنا وذريتنا ومنكنش بذرة ولا حصاد للشيطان ولا لأعداء الإسلام\nفباختصار كده،\nوجهة نظر رسول الله ﷺ كانت إنه عايز يتألف قلوب كبار القبائل والعشائر عشان الإسلام يتقوى بهم وده عن طريق بإنفاق أموال زيادة من الخمس عليهم؛\nلأن أسياد القوم إذا أَلفوا الإسلام وقوِيَ إيمانهم يحصل منهم خير كثير، وتَتّبعهم على ذلك قبائلهم وعشائرهم.\nوبكده احنا فهمنا وجهة نظر رسول الله ﷺ كااااملة وشوفنا إن فعلا وجهة النظر دي كانت صحيحة وعادلة ومفيهاش أي ظلم\nهقولكم بقى مثال والمثال ده هنبني عليه باقي الأحداث إللي هتحصل بعد كده\nشوفوا،\nلو في واحد بيشتغل في شركة، والشخص ده خدم في الشركة دي بكل طاقته لمدة عشر سنين، وقدم للشركة دي كل ما إللي يقدر عليه، \nوالشركة دي كانت صغيرة في بدايتها، وبعد كده الشركة كبرت على كتفه زي ما بنقول،\nومع المجهود ده كله فهو مكنش بيطلب لنفسه أي حاجة زائدة عن الحد، يعني المرتب وخلاص،\nوكمان ساعات مكنش بيبقى في مرتب أصلا، مع إنه كان بيشتغل أكتر من المطلوب منه،\nوبعد فترة جاء رجل تاني يعمل في الشركة دي مع الشخص المجتهد ده، ولكن الرجل الجديد طلع سيئ الخُلق غير منضبط في عمله، \nبيحضر في أوقات ويغيب في أوقات تانية أكتر، وبيتحدث بالسوء عن صاحب الشركة إللي صاحبنا المجتهد خدمه بإخلاص طول السنين العشر إللي فاتت،\nوبعد كده في أواخر السنوات العشر الشركة حققت نجاح كبير جدا، وربحت صفقة كبيرة جداً كان صاحبنا المجتهد هو  السبب فيها،\nوكان الموظف الجديد ده مُعوِّق للصفقة دي،\nوبعد ما تمت الصفقة جاء صاحب الشركة فأعطى الاتنين الراتب الشهري الرسمي بتاعهم، \nوبعدين صاحب الشركة راح أعطي الموظف الجديد الغير المنضبط خمسة مليون جنيه مكافأة، ولم يعطِ للموظف المجتهد أي حاجة،\nتخيلوا إحساس الموظف المجتهد ده هيكون عامل إزاي\nكل واحد فينا كده يحط نفسه مكان الموظف المجتهد ده ويفكر كده هو ممكن يعمل إيه في موقف زي ده\nأهه يا جماعة ده بالضبط كان وضع الأنصار رضي الله عنهم جميعا\nالأنصار كانوا همّ الموظف المجتهد ده إللي قامت على أكتافهم الدولة الإسلامية،\nوقادة الأعراب إللي رسول الله ﷺ أعطاهم زيادة من الغنائم كانوا همّ الموظف إللي كان بيعوّق قيام الدولة الإسلامية\nوطبعا انتم شوفتم تضحية الأنصار على مدار السنين إللي فاتت دي كلها،\nيعني مننساش إن شهداء أحد كانوا أكثرهم من الأنصار، وكان الأنصار بيقتسموا أموالهم مع المسلمين،\nوفي غزوة بدر كان الأنصار ثُلُثَيْ الجيش، وشاركوا مع رسول الله ﷺ في كل المعارك،\nوحتى لما المسلمين هربوا في بداية معركة حنين كانوا همّ إللي رجعوا وقاتلوا حول رسول الله ﷺ ودافعوا عنه بعد ما نادى عليهم العباس، وكانوا همّ سبب النصر،\nوبعد كل ده لم يعطِ رسول الله ﷺ للأنصار شيئا، زي ما قال أنس بن مالك رضي الله عنه،\nوده على الرواية إللي بتقول إن رسول الله ﷺ أعطى للكل ولم يعطِ للأنصار،\nأما الرواية التانية فرسول الله ﷺ أعطى للأنصار نصيبهم من الغنائم العادية زيهم زي الباقيين،\nزي ما قلنا في المثال كده المرتب العادي، لكن المكافأة العظيمة مكنتش لهم كانت لغيرهم، \nفكده كده بالوضع إللي شرحناه ده فالأنصار يُعتبروا لم يأخذوا شيئا فعلا\nوأصلا كان من عادة رسول الله ﷺ إنه يكافئ المجتهد في القتال بزيادة في الأجر،\nلكن دلوقتي مكنش في مجال إن رسول الله ﷺ يكافئهم ؛ لأن كان له وجهة نظر مختلفة وإللي شرحناها المرة إللي فاتت والمرة دي،\nفالأنصار لما شافوا إللي حصل وشافوا توزيع الغنائم على الناس إللي مكنوش بيعملوا حاجة غير إنهم كانوا معوقين للمسلمين؛ تأثروا جدا وحزنوا حزن شديد جدا، \nوقال بعضهم:\n\"إذَا كَانَتِ الشِّدَّةُ فَنَحْنُ نُدْعَى، وَتُعْطَى الغَنَائِمُ غَيْرَنَا\"\nيعني في وقت الشدة ووقت ما كان رسول الله ﷺ محتاجنا دعانا،\nولما جاء وقت توزيع الغنائم إللي احنا السبب الرئيسي في وجودها مخدناش منها حاجة،\nوفي رواية تانية قالوا:\n\" يَغْفِرُ اللَّهُ لِرَسولِ اللَّهِ ﷺ ، يُعْطِي قُرَيْشًا ويَدَعُنَا، وسُيُوفُنَا تَقْطُرُ مِن دِمَائِهِمْ\"\nيعني بقى رسول الله ﷺ بيعطي لقريش إللي لسه كنا بنقاتلهم قريب جدا، واحنا لأ، \nفهمّ حسّوا إن رسول الله ﷺ بدأ يميل لأهله وعشيرته من قريش ويُفضّلهم بالعطاء،\nالموقف صعب جدا على الأنصار يا جماعة، ولو فعلا حطينا نفسنا مكانهم هنحس بألمهم،\nوده واحنا عارفين وجهة نظر رسول الله ﷺ في إللي عمله وشوفنا أثر قراره الحكيم،\nفما بالكم بقى بالأنصار إللي مكنوش فاهمين وجهة النظر دي ولا مستوعبينها وكانوا حاسين إنهم كده خلاص اتركنوا على الرف، ورسول الله ﷺ حن بقى لأهله وعشيرته\nالكلام طبعا وصل لرسول الله ﷺ، وإللي أخبره بالكلام ده  هو سعد بن عبادة سيد الأنصار، فسأله رسول الله ﷺ عن رأيه الشخصي،\nفقال له سعد: أنا رجل من قومي، يعني هو حاسس بنفس إحساس الأنصار،\nيا ترى بقى رسول الله ﷺ هيتعامل مع الموقف الخطير ده إزاي؟\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 205, "l": "الجزء 179 | احداث السنه الثامنه من الهجرة | منهج رسول الله في حل المشاكل", "u": "https://www.facebook.com/groups/710210019782034/permalink/836547023814999/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وتسعة_وسبعون\n#أحداث_السنة_الثامنة_من_الهجرة\n#منهج_رسول_الله_في_حل_المشاكل\nوقفنا المرة إللي فاتت عند الكلام إللي بعض الأنصار قالوه،\nوكانوا قالوا:\n\" إذَا كَانَتِ الشِّدَّةُ فَنَحْنُ نُدْعَى، وَتُعْطَى الغَنَائِمُ غَيْرَنَا\"\nوفي رواية تانية قالوا:\n\" يَغْفِرُ اللَّهُ لِرَسولِ اللَّهِ ﷺ ، يُعْطِي قُرَيْشًا ويَدَعُنَا، وسُيُوفُنَا تَقْطُرُ مِن دِمَائِهِمْ\"\nواحنا نلاحظ هنا إن حتى والأنصار زعلانين محدش فيهم تعدّى حدود الأدب مع رسول الله ﷺ\nسعد بن عبادة سيد الأنصار لما سمع الكلام ده، راح لرسول الله ﷺ وقال له:\n\" يا رسول الله! إن هذا الحي من الأنصار قد وَجَدوا عليك في أنفسهم لِمَا صَنعت في هذا الفيء الذي أصبت،\nقَسمتَ في قومك، وأعطيتَ عطايا عِظاماً في قبائل العرب،\nولم يكن في هذا الحي من الأنصار منها شيء\"\nيعني بيقول لرسول الله ﷺ إن الأنصار زعلوا منه بسبب القسمة إللي قسمها بين العرب وقريش، ولم يُعطهم من التقسيم ده شيء زي ما شرحنا المرة إللي فاتت كده،\nفقال له رسول الله ﷺ:\nفأين أنت من ذلك يا سعد؟\nيعني انت إيه رأيك في الموضوع يا سعد، \nفقال سعد: يا رسول الله! ما أنا إلا من قومي!\nيعني أنا عندي نفس إحساسهم وإن كنت مقلتش نفس الكلام إللي قالوه.\n☆الأنصار بشر يا جماعة مش ملائكة، والبشر جُبِلُوا على حب المال، فإذا كان المال ده حلال فإيه المانع من طلبه\nوخاصة إذا كانوا حاسين إنهم هم السبب في الثروة دي\nده غير بقى إن في نقطة تانية مهمة خلّت الأنصار قلقانين وخايفين، وهي إن رسول الله ﷺ مع الوضع الجديد ده ممكن يتركهم ويرجع يعيش في مكة،\nومكة هي خير بقاع الأرض، وأحب بلاد الله إلى قلب رسول الله ﷺ ،\nوفيها الأهل والعشيرة، وفيها الطفولة والشباب والذكريات، وفيها قريش أعز قبائل العرب،\nوهي أهم مركز من مراكز التجارة في الجزيرة العربية، ويأتي لها الناس جميعاً طول السنة من كل مكان، \nوفيها مقومات كثيرة تخليها تكون هي عاصمة جديدة للدولة الإسلامية\nفلو قرر رسول الله ﷺ العودة لمكة هتبقى حاجة متوقعة  ومحدش هيقدر يلوم عليه،\nومننساش إن الانصار قالوا لرسول الله ﷺ صراحة كده\nقبل أقل من شهرين لما فُتحت مكة إنهم خايفين إن رسول الله ﷺ يرجع لمكة،\nورسول الله ﷺ ساعتها طمنهم إنه هيرجع معاهم تاني للمدينة ومش هيقعد في مكة وقال لهم: \n《المحيا محياكم، والممات مَمَاتُكم》\nلكن لمّا حصل توزيع الغنائم بالصورة إللي شرحناها دي، ثارت الشكوك في قلوب الأنصار،\nوخافوا إن ممكن يكون الظرف اتغير، والأحداث الجديدة غيّرت من الصورة، وإن رسول الله ﷺ بقى له رأي جديد في الموضوع، وإنه هيرجع لمكة المكرمة ومش هيرجع معهم إلى المدينة\nفالموقف ده بداية لأزمة خطيرة للدولة الإسلامية؛ لأن انتشار الشعور ده في الطائفة المهمة دي من الجيش هيؤدي لكوارث مستقبلية ممكن تدمر الدولة الإسلامية \nفكان لازم تصرف حكيم جدا في التعامل مع الموقف ده،\nوفعلا رسول الله ﷺ عالج المشكلة بطريقة فريدة تجمع بين إقناع العقل وإرضاء العاطفة\nتعالوا نشوف رسول الله ﷺ عمل إيه وبعدين نحلل إللي عمله ده\nرسول الله ﷺ قال لسعد بن عبادة إنه يجمع الأنصار في خيمة، وطلب إن إللي يجتمع هم الأنصار فقط ومحدش تاني يحضر الاجتماع ده،\nفلمّا اجتمعوا دخل عليهم رسول الله ﷺ وقبل ما يتكلم إتأكد إن محدش تاني موجود في المكان ده غير الأنصار،\nوبعد كده بدأ رسول الله ﷺ يتكلم،\nحمد الله وأثنى عليه ثم قال للأنصار:\n\"يا مَعْشَرَ الأنْصَارِ، ما حَدِيثٌ بَلَغَنِي عَنْكُمْ؟ وَجْدَةً وجدتّمُوها عليّ في أنفسكم؟ \nيعني إيه صحة الكلام إللي وصلني عنكم انكم قلتوه، و انكم زعلانين مني؟\nفقال فقهاء الأنصار وعلماؤهم وسَابِقوهم:\n\"أما ذَوِي رأينا يا رسول الله فلم يقولوا شيئاً،\nوأما أُناس حديثةٌ أسنانهم قالوا: يغفر الله لرسول الله يعطي قريشاً ويتركنا، وسيوفنا تقطر من دمائهم\"\nيعني بيقولوا إن إللي قال الكلام ده هم مجموعة من الشباب المتحمسين، أما أصحاب الرأي والعلم محدش فيه قال حاجة،\nفقال لهم رسول الله ﷺ:\nيا معشر الأنصار، ألَم آتِكُم ضُلَّالًا فهداكُم اللهُ بي؟\nوعالةً فأغناكُم اللهُ بي؟\nوأعداءً فألَّفَ اللهُ بينَ قلوبِكُم بي ؟ \n☆ساعات الإنسان لما بيتعود على نعمة معينة بينساها، فبيبقى محتاج حد يذكّره بيها،\nوده إللي رسول الله ﷺ عمله هنا، بدأ بيلفت نظرهم للنعم إللي نسيوها، \nيعني بصوا لنص الكوباية المليان، انتم أه لم تأخذوا من العطايا، لكن هل فعلا لم تأخذوا شيئا على الإطلاق؟\nرسول الله ﷺ لم يُقدم لكم شيئاً قبل كده؟!\nألم ينفعكم الإسلام؟!\nألم تستفيدوا من انضمامكم إلى الكيان الجديد ده في الدولة الإسلامية؟!\nهل نسيتم يوم دعوتكم للإسلام، وكنتم تسجدون لأصنام صنعتموها بأيديكم؟\nنسيتم الجاهلية؟!\nنسيتم التربية الإسلامية لكم يوماً بعد يوم، وسنة بعد سنة؟!\nنسيتم إزاي انتقلتم بالإسلام من الظلمات إلى النور؟!\nنسيتم إزاي بقى لكم ذِكر وشأن مش بس في جزيرة العرب، بل في العالم كله؟\nو مش بس في زمانكم، بل وإلى يوم القيامة؟!\nمش دي مكاسب واقعية؟\n《ألَم آتِكُم ضُلَّالًا فهداكُم اللهُ بي؟》\nوانتم مش بس كسبتم الآخرة، لكن ده ربنا أغناكم كمان في الدنيا بنعمه،\nيعني انتم دلوقتي دولة لها كيان، ولكم جيوش هنا وهناك، وعندكم معاملات مع جميع العرب،\nلكم انتصارات مع دول العالم، لكم تجارة هنا وهناك، لكم صَوِلات وجِوَلات، وغنائم وانتصارات،\nهل كان ده وضعكم قبل الإسلام؟\n《ألم آتكم عالةً فأغناكُم اللهُ بي》\nنسيتم حروبكم الدامية؟\nنسيتم دماء الأوس والخزرج إللي سالت سنين على أرض يثرب؟!\nنسيتم يوم بُعاث؟!\nنسيتم الكراهية والحقد والضغينة إللي كانت تملأ قلوبكم قبل الإسلام؟!\n《ألم آتكم أعداءً فألَّفَ اللهُ بينَ قلوبِكُم بي》\nهو ده النّص المليان من الكوباية، وهي دي الإيجابيات، \nدي ثلاث نِعم من نِعم كثيرة لا تعد ولا تحصى،\nهل بقى النِّعم دي أثقل ولّا المائة ناقة إللي أخذها هذا أو ذاك؟\n☆مش صح إننا ننظر للسلبيات بس، أو خلينا نقول نص الكوباية الفاضي؛ لأن كده الإنسان هيبقى شديد التشاؤم،\nوبرده مينفعش ينظر لنص الكوبابة المليان بس فيكون شديد التفاؤل بصورة غير واقعية\nلكن لازم يكون في نظرة متوازنة للأمور، نظرة للسلبيات والإيجابيات مع بعض\nطبعا الكلام كان شديد جدا على الأنصار، ووقع عليهم كالصخر خلاهم يرجعوا لأرض الواقع ويشوفوا النعم إللي عندهم،\nو ساعات العلاج بيبقى مؤلم جداً لكنه نافع،\nفبالرغم إن الكلام كان شديد على الأنصار إلا إنهم مكنوش بيقولوا غير كلمة واحدة بس:\n\"لله ولرسوله المَنّ والفضل\"\nكانوا في غاية الأدب مع رسول الله ﷺ، وكانوا بيسمعوا كلام رسول الله ﷺ وساكتين، محدش فيهم اتكلم عن أفضالهم على الدولة الإسلامية،\nلكن رسول الله ﷺ مش ناسي فضلهم وكان مُشفق عليهم، وهو ﷺ كان حاسس بخوفهم من إنه يسيبهم ويرجع لقريش،\nفقال لهم في حنان ظاهر: \nألا تجيبوني يا معشر الأنصار؟!\nيعني إيه ردكم على الكلام إللي قلته ده،\nفقال الانصار بكل أدب:\n\"بماذا نجيبك يا رسول الله؟! لله ولرسوله المن والفضل\"\nيعني احنا معترفين بكل إللي انت قلته، وإللي أخذناه أكثر بكثير من إللي اتمنع عنا،\nفقال لهم رسول الله ﷺ في تواضع وهو يرفع جداً من قيمتهم:\n\"أما والله لو شئتم لقُلتُم فلصَدَقْتم ولصُدّقُتم:\nأتيتَنا مُكَذّبا فصدقناك، ومخذُولاً فنصرناك، وطرِيداً فآوَيْناك، وعائلاً فأغنيناك\"\nيعني إن كان أدبكم أيها الأنصار يمنعكم من ذِكر فضلكم عليّ، أنا شخصياً لا أُنكره ولا أجْحده،\nبل أعترف به وأقدّره\nمن غيركم مكنش هيبقى في دولة، ومن غيركم مكنش هيبقى في نُصرة،\nصدقتمُوني ونصرتمُوني وآويتموني وأغنيتُموني،\nفهنا الأنصار حسوا بحرج شديد من الكلمات دي، ومزادوش على إنهم قالوا:\n\"المَنُّ لله ورسوله\"\nفقال لهم رسول الله ﷺ في رقة شديدة:\n\"أوَجَدتُم في نفوسكم يا معشر الأنصارِ في لُعاعةٍ مِن الدنيا تألَّفتُ بها قومًا أسلَموا، ووَكلتُكم إلى ما قسم الله لكم من الإسلامِ؟! \nأفلا ترضوْنَ يا معشر الأنصارِ أن يذهب الناسُ إلى رِحالِهِم بالشَّاءِ والبَعيرِ، وتذهبون برسول الله إلى رِحالِكم؟ \nفوَالذي نفسي بيده، لو أن الناس سلكوا شِعبًا وسلكَت الأنصارُ شِعبًا، لسلكتُ شِعبَ الأنصارِ،\nولولا الهجرةُ لكنتُ امرَأً من الأنصارِ، اللهم ارحم الأنصارَ، وأبناءَ الأنصارِ، وأبناءَ أبناءِ الأنصارِ\"\nيعني رسول الله ﷺ بيقولهم:\nانتم زعلتم عشان شوية مال بسيط صرفتهم على ناس عشان أتألف بيه قلوبهم، وسيبتكم انتم لإسلامكم وثباتكم عليه؟\nمش معنى إني قدمتهم عليكم إني بحبهم بصورة أكبر،\nأو عشان أنا مثلا مقدر موقفهم البطولي،أو أداءهم المتميز، بالعكس أنا وبكل صراحة عارف إن قلوبهم مترددة،\nوإن أقدامهم لسه مش راسخة في الإسلام، عشان كده أنا أعطيتهم،\nأمّا انتم فأنا واثق في إيمانكم وإن الموضوع مش هيأثر فيكم؛ لأن همكم الآخرة،\nوهمّ إن كانوا كسبوا النّوق والشياه فانتم  كسبتم رسول الله\n ﷺ،\nانتم تحبوا إنكم ترجعوا لبلدكم بالأموال ولّا ترجعوا برسول الله ﷺ؟\nوبدأ رسول الله ﷺ يُبين للأنصار مكانتهم عنده، فأقسم إنه لو الأنصار اختاروا طريق والناس اختاروا طريق تاني، هو هيختار طريق الأنصار، \nولولا الهجرة وإنه ﷺ من المهاجرين كان هيختار إنه يكون واحد من الأنصار، \nوبعدين دعا لهم رسول الله ﷺ ودعا لأبناءهم وأحفادهم\nفبكى الأنصار رضي الله عنهم بكاء شديد لحد ما أَخْضَلُوا لِحَاهُم، يعني كل واحد فيهم من كثرة بكائه لحيته اتبلت  بالدموع، \nفقال لهم رسول الله ﷺ وهو يصبرهم ويذكرهم الآخرة وإن التعويض الرئيسي عن كل ألم وكل خسارة هيكون هناك:\n\"إنكم ستلقون بعدي أَثَرَة شديدة، فاصبروا حتى تلقَوْنيِ على الحوض\"\nيعني هييجي بعدي إللي يُفَضّل عليكم غَيرَكم في الأموالِ وغيرِها، فَيُعطِيهم مَا لا يُعطِيكم، ويَستعملُهم في الوظائفِ والولاياتِ ما لا يستعملُكم؛\nفاصبرُوا على إللي هتشوفوه في الدُّنيا لحد ما تقابلوني على الحوضِ في القيامةِ سالِمينَ مِنَ التَّنافُسِ والتَّباغُضِ في حُطامِ الدُّنيا، فعندها تُوفَّونَ أُجوركم مِنَ اللهِ تعالى\nفقال الأنصار:\n\"رضينا بالله ربًّا، ورسوله قسمًا\"\nيعني خلاص احنا مش عايزين أي حاجة، ورضينا إن نصيبنا يبقى رسول الله ﷺ،\nوبكده انتهت الأزمة دي بسبب تصرف رسول الله ﷺ الحكيم \nخلونا بقى نحلل المنهج إللي رسول الله ﷺ اتبعه في حل الأزمة دي، عشان نقدر نطبقه في حياتنا العملية لو قابلتنا مشكلة زي كده\n◇أول نقطة في المنهج إللي رسول الله ﷺ اتبعه كان إنه:\nحل الأزمة بسرعة من البداية ومأجلش الموضوع،\nيعني لما وصل له الكلام مقلش مثلا زي ما في ناس بتقول:\nمادام أنا صح خلاص ميهمنيش كلام الناس،\nأو مادام ربنا راضي خلاص مش لازم أبيّن للناس الموضوع واسترضيهم،\nورسول الله ﷺ يا جماعة كان قراره صحيح تماااما وربنا مُؤيِّد له، بدليل إن الوحي منزلش يعارض قرار رسول الله ﷺ في التقسيم إللي حصل،\nفما بالكم بقى باللي أقل منه، محتاج يعمل إيه\nوعلى الرغم من شدة إيمان الأنصار ومكانتهم فرسول الله ﷺ مقلش إن الأنصار دول مؤمنين جدا وإللي حصل ده مش هيأثر على مستقبل الدولة الإسلامية،\nوالأيام كفيلة بحل القضايا إللي زي كده، وأنا رسول الله ويجب عليهم يطيعوني،\nمفيش حاجة من دي حصلت، على طول وفورا وبدون تأخير أمر بجمع الأنصار عشان يستفهم منهم ويوضح لهم وجهة نظره ﷺ\n◇النقطة التانية:\nإن رسول الله ﷺ منع انتشار الموضوع وده عن طريق إنه اجتمع مع الأنصار فقط، يعني هو ﷺ مكنش عايز عامة المسلمين يعرفوا،\nوطبعا ده لسببين:\n¤أولا:\nعشان محدش يُفْتَن بالشّبهة إللي حصلت دي وإن رسول الله ﷺ كده ظلم الأنصار وينقسم المسلمين لمؤيد ومعارض وتحصل مشكلة أكبر.\n¤ثانيا:\nعشان محدش ياخد موقف سلبي من الأنصار لما يتبين لهم خطأءهم ويفهموا وجهة نظر رسول الله ﷺ،\nوبكده تفضل صورة الأنصار جميلة ومحفوظة عند عامة الناس.\n◇النقطة الثالثة:\nلقاء أصحاب الأزمة بصورة مباشرة من غير وَساطة، يعني هو اتكلم مع أصحاب المشكلة نفسهم ومدخلش حد تاني في الموضوع؛\nلأن الواسطة يا جماعة ممكن ميقدرش يوصل المعنى المطلوب إللي الطرفين عايزين يوصلوه لبعض،\nده غير إن شعور الجنود عامة بالقرب من قائدهم بيحل كتير  جداً من المشاكل إللي ممكن تحصل.\nوده يعملنا إن لما تكون في مشكلة مع حد في حياتنا نتكلم مع صاحب المشكلة نفسه مش إننا نتكلم مع ده وده وصاحب المشكلة هو آخر من يعلم\n◇النقطة الرابعة:\nالصراحة والوضوح وراء الفعل الذي أغضب أصحاب الأزمة، وذكر السبب الحقيقي للفعل.\nيعني رسول الله ﷺ قالهم بكل وضوح كده هو ليه قسّم التقسيمة دي،\nوشرح لهم وجهة نظره فيها وإنه معملش كده عشان بيحبهم أكثر من الانصار، لأ، ده عشان هُمّ إيمانهم مش راسخ زي الأنصار.\nفاحنا يا جماعة لما نواجه مشكلة مع حد ووصل لنا عنه كلام لازم نحل الموضوع بسرعة ونوضح للطرف التاني ده وجهة النظر بكل صراحة ووضوح،\nوطبعا هنا مننساش موقف سعد بن عبادة الرائع وموقف الأنصار نفسهم في صراحتهم، وهي إللي كانت سبب رئيسي في حل المشكلة،\nيعني لو كانت نفوسهم شايلة وكبّروا دماغهم وادّعوا بمثالية إن مفيش مشكلة وأنكروا وجود مشكلة أساسا،\nكانت المشكلة هتكبر جواهم والحل كان هيبقى أصعب ويمكن يكون مستحيل،\nواحنا في واقعنا الحالي للأسف في ناس خسروا بعض بسبب عدم الصراحة في عرض المشكلة، وعدم المُسارعة في حل المشكلة\nفاحنا كده بقى محتاجين : \nسرعة وصراحة في حل المشكلة وكمان مننشرش المشكلة وسط الناس بدون داعي، ومندخّلش حد بيننا وبين صاحب المشكلة، والحوار يكون مع صاحب المشكلة هو نفسه\n◇النقطة الخامسة:\nالنظر بتوازن إلى الموضوع، و لَفْت أنظار أصحاب الأزمة إلى ما حصّلُوه من إيجابيات،\nوده حصل لما رسول الله ﷺ قعد يذكّرهم باللي استفادوه من الإسلام، وقالهم ألم آتكم ضُلّالا فهداكم الله بي، إلى آخر الكلام إللي قلناه،\nفلما نتكلم مع حد في بينا وبينه مشكلة منبصش بس على السلبيات إللي ضايقتنا منه ولكن نبص كمان على إيجابياته وهو كان إزاي سبب في سعادتنا في يوم من الأيام.\n◇النقطة السادسة:\nالاعتراف بقيمة أصحاب الأزمة وفضلُهم ورفع معنوياتهم.\nوده لما رسول الله ﷺ اعترف بفضل الأنصار وقالهم إنه جاءهم طريد فآووه ونصروه وصدقوه،\nفالأنصار لهم فضل واضح ومحدش ينكره، فرسول الله ﷺ عرّفهم إنه مش ناسي فضلهم وحسسهم بقيمتهم ومقدر مجهودهم، وده طبعا رفع معنوياتهم جدا\n◇النقطة السابعة:\nتَهْوِين حجم الخسارة التي خسرها أصحاب الأزمة إن كانت هيّنة.\nوده لما رسول الله ﷺ قالهم:\n \"أوَجَدتُم في نفوسكم يا معشر الأنصارِ في لُعاعةٍ مِن الدنيا تألَّفتُ بها قومًا أسلَموا\"\nيعني مهما كانت الخسارة إللي حصلت فهي لُعاعةٍ مِن الدنيا،\nيعني حاجة بسيطة جدا مش مستاهلة، والأجر في الآخرة أعظم من أي شيء\n◇النقطة الثامنة:\n تحريك عواطف ومشاعر أصحاب الأزمة، بالإضافة إلى إقناع عقولهم.\nوده لما رسول الله ﷺ قالهم:\n\"أفلا ترضون يا معشر الأنصار أن يذهب الناس بالشاة والبعير، وترجعون برسول الله ﷺ إلى رحالكم\"\nفهنا رسول الله ﷺ حرّك مشاعرهم بالنقطة دي بالذات؛ لأنهم أصلا كانوا قلقانين وخايفين إن رسول الله ﷺ يتركهم ويرجع لقريش\nفرسول الله ﷺ استعمل الحُجة والعقل والعاطفة في توضيح وجهة نظره.\n◇النقطة التاسعة:\nالدعاء المُخلص لهم أن يرحمهم الله عز وجل وأن يثبت أقدامهم، وده كان لما قالهم:\n\"اللهم ارحم الأنصارَ، وأبناءَ الأنصارِ، وأبناءَ أبناءِ الأنصارِ\"\n◇النقطة العاشرة والأخيرة:\nالتذكير بالآخرة، وإن الإنسان في الدنيا ممكن يخسر حاجة في مقابل إن الكل يكسب،\nيعني الأنصار خسروا العطايا إللي رسول الله ﷺ أعطاها لغيرهم، لكن كل المسلمين ودولة الإسلام كسبوا الناس إللي\nرسول الله ﷺ تألف قلوبهم دول\n☆سؤال مهم بقى،\nليه رسول الله ﷺ مقعدش مع الأنصار واستشارهم قبل ما يوزع العطايا دي أصلا وبكده نتجنب الموقف الصعب ده\nشوفوا،\nأولا كده الخُمس إللي رسول الله ﷺ وزع منه على المؤلفة قلوبهم ده، مِلك لله ولرسوله يتصرف فيه رسول الله ﷺ زي ما هو عايز على حسب المصلحة إللي هو شايفها هتخدم الإسلام والمسلمين،\nومحدش له أصلا إنه يعترض؛ لأن الكل أخد نصيبه خلاص من الأربع أخماس التانيين\nثانيا:\nرسول الله ﷺ ميعرفش الغيب إلا إللي ربنا بيقوله عليه، \nفهو مكنش يعرف ولا كان متخيل إن حاجة زي كده ممكن تزعل الأنصار؛ \nلأنه عارف قوة إيمانهم وزهدهم في الدنيا، وعارف حرصهم على مصلحة الإسلام والمسلمين،\nوكان ممكن ربنا يوحي لرسول الله ﷺ بالغيب إللي هيحصل، بإن في أزمة هتحصل عند الأنصار ويقوله يقعد معاهم ويفهمهم، وخلاص الأزمة تتحل،\nطيب وبعدين؟\nالقادة إللي هييجوا بعد رسول الله ﷺ هيتعاملوا في الموقف إللي زي كده إزاي ومفيش وحي\nرسول الله ﷺ قدوة للناس بصفة عامة، وقدوة لكل قائد هييجي بعده بصفة خاصة،\nفكان لازم رسول الله ﷺ يتصرف ويعمل إللي يشوفه مناسب، ويحصل الاعتراض من الأنصار عشان نتعلم منهم أدب الاعتراض،\nونتعلم من رسول الله ﷺ طريقة حل المشاكل زي ما شوفنا كده \nقصة رسول الله ﷺ مع الأنصار في الموقف ده مليانة دروس وعِبر، تخيلوا لو مكنتش حصلت، كنا هنتعلم الدروس والعبر دي إزاي\nفمش كل حاجة ظاهرها شر أو ألم بتبقى فعلا كده،\n《فَعَسَى أَنْ تَكْرَهُوا شَيْئًا وَيَجْعَلَ اللَّهُ فِيهِ خَيْرًا كَثِيرًا》\nشوفتوا إزاي سيرة رسول الله ﷺ عبارة عن منهج عملي للخروج من كل أزمة في حياتنا مهما كانت كبيرة\nوصدق رسول الله ﷺ لما قال:\n\" إِنِّي قَدْ تَرَكْتُ فِيكُمْ مَا إِنِ اعْتَصَمْتُمْ بِهِ فَلَنْ تَضِلُّوا أَبَدًا، كِتَابَ اللَّهِ وَسُنَّةَ نَبِيِّهِ ﷺ\"\nلو اتبعنا منهج رسول الله ﷺ في حل المشاكل كده مش هيبقى في قطيعة وغيبة ومشاكل بين المسلمين\n☆في ملحوظة مهمة جدا\nالنقط العشرة إللي قلناهم دول ملهمش أي فايدة ومش هتجيب نتيجة إلا مع ناس قلوبها نقية ودرجة إيمانها عالية وهدفهم الجنة فعلا وعايشين حياتهم لله\nلأن احنا ممكن نعمل فعلا الخطوات دي كلها في حل مشاكلنا مع الناس لكن الطرف التاني مفيش منه أي استجابة\nفمتفكروش إن ده خلل في منهج رسول الله ﷺ، لأ، الخلل في الطرف التاني إللي في قلبه مرض،\nأو ممكن يكون في الطرف نفسه إللي بيحل المشكلة، يعني ممكن ميكونش طبق منهج رسول الله ﷺ صح، فعشان كده مفيش نتيجة\nزي كده البذرة لما بنيجي نحطها في التربة،\nمش احنا بنختار التربة المناسبة للبذرة عشان تطلع الثمرة\nأهه البذرة دي مهما كانت جودتها عالية ومن أحسن أنواع البذور، فهي عمرها ما تطلع ثمرة لو الأرض إللي هتتزرع فيها أرض فاسدة بور لا تصلح للزراعة\nوكذلك العكس، ممكن الأرض هي إللي كويسة والبذرة هي إللي فاسدة، أو ممكن همّ الاتنين فيهم مشكلة\nفمش هنعرف الخلل فين غير لما نحاول نطبق منهج رسول الله ﷺ مرة واتنين وتلاتة وعشرة،\nومحدش ييأس؛ لأن ربنا بيحاسبنا على المحاولات مش بيحاسبنا على النتيجة،\nفخلوا عندكم يقين كده إن منهج رسول الله ﷺ مفهوش أي مشكلة، ومش محتاج تعديل،\nالمشكلة في طريقة التطبيق أو في الشخص إللي بنطبق معاه المنهج ده\nوبكده انتهت قصة توزيع غنائم حنين، \nأَلّف رسول الله ﷺ ﷺ قلوب البعض واسترضى آخرين، واتحلت كل الأزمات، وكانت الأيام دي من أسعد أيام المسلمين في الفترة النبوية،\nطبعا في أحداث تانية كتير حصلت بس هيبقى صعب إني اشرحها كلها وكمان فيها الضعيف والمختلف في صحته،\nفأنا قلت لكم أهم الأحداث إللي حصلت\nوإللي عايز يستزيد بقى، ممكن يرجع مثلا لكتاب\n《البداية والنهاية》لابن كثير،\nوكتاب:\n《السيرة النبوية كما جاءت في الأحاديث الصحيحة》 لمحمد الصوياني. \nبعد بقى الانتهاء من توزيع الغنائم كلها ورضا كل فريق بما أخذ، سواء من الجزء الرئيسي من الغنيمة أو من الخمس إللي رسول الله ﷺ وزعه،\nحصلت مفاجأة ضخمة غير متوَقعة\nإيه المفاجأة إللي حصلت دي؟\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 206, "l": "الجزء 180 | اسلام هوزان", "u": "https://www.facebook.com/groups/710210019782034/permalink/836547177148317/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وثمانون\n#أحداث_السنة_الثامنة_من_الهجرة\n#إسلام_هوازن\nوقفنا المرة إللي فاتت عند المفاجأة الضخمة الغير متوقعة إللي حصلت بعد توزيع الغنائم،\nالمفاجأة كانت : مَجيء وفْد من هوازن لمقابلة رسول الله ﷺ في وادي الجُعرانة،\nوالوفد ده كان من بطون بني نصر وبني سعد وكل بطون هوازن الأخرى باستثناء قبيلة ثقيف،\nيعني قبيلة ثقيف الوحيدة هي إللي مبعتتش حد يمثلها في الوفد ده،\nوكان الوفد ده مكون من أربعة عشر نفراً،\nوالمفاجأة الأكبر إن الوفد ده جاء عشان يعلن إسلامه وإسلام هوازن\nلقوا نفسهم خسروا كل شيء، \nخسروا نساءهم وأبناءهم وأموالهم وأنعامهم، \nخسروا حاضرهم وهيخسروا مستقبلهم كمان لو هم بقيوا على الشرك،\nفموقفهم كان صعب، ففكروا إنهم لو رجعوا لرسول الله ﷺ فهو ممكن يقبل منهم إسلامهم ويرجع لهم بعض الممتلكات،\nهو واضح جداً إنهم لم يأتوا حباً في الإسلام لكن عشان مصلحتهم\nلكن معظم الناس إللي بيدخلوا الإسلام ساعتها عشان شيء دنيوي بيحبوا الإسلام  بعد فترة من الزمن،\nفهمّ في النهاية هيحسوا بقيمة الإسلام بعد ما يعيشوا فيه\nالمهم، \nوفد هوازن قعد مع رسول الله ﷺ وأعلنوا إسلامهم وبعدين قالوا لرسول الله ﷺ:\n\"يَا رَسُولَ اللَّهِ، إِنَّا أَصْلٌ وَعَشِيرَةٌ، وَقَدْ أَصَابَنَا مِنَ الْبَلَاءِ مَا لَمْ يَخْفَ عَلَيْكَ، فَامْنُنْ عَلَيْنَا مَنَّ اللَّهُ عَلَيْكَ\"\nوقام الخطيب بتاعهم وبدأ يتكلم فقال:\n\" يَا رَسُولَ اللَّهِ، إِنَّ مَا فِي الْحَظَائِرِ مِنِ السَّبَايَا خَالَاتُكَ وَعَمَّاتُكَ وَحَوَاضِنُكَ اللَّاتِي كُنَّ يَكْفُلْنَكَ،\nوَلَوْ أَنَّا مَلَحْنَا لِابْنِ أَبِي شَمِرٍ أَوِ النُّعْمَانِ بْنِ الْمُنْذِرِ، ثُمَّ أَصَابَنَا مِنْهُمَا مِثْلُ الَّذِي أَصَابَنَا مِنْكَ، رَجَوْنَا عَائِدَتَهُمَا وَعَطْفَهُمَا،\nوَأَنْتَ يَا رَسُولَ اللَّهِ خَيْرُ الْمَكْفُولِينَ.\nثُمَّ أَنْشَأَ يَقُولُ:\nامْنُنْ عَلَيْنَا رَسُولَ اللَّهِ فِي كَرَمٍ ... فَإِنَّكَ الْمَرْءُ نَرْجُوهُ وَنَدَّخِرُ\nيعني بيقولوا لرسول الله ﷺ إن في بينهم رحم، وأصلهم واحد، \nواحنا كنا قلنا قبل كده في الجزء المائة واحد وسبعون لو تفتكروا إن هوزان جاية من فرع عَيْلاَن وقريش من فرع إِليَاس، يعني يُعتبروا أبناء عم،\nفهمّ بيذكّروا رسول الله ﷺ بأصولهم وإن إللي موجودين في السبي دول خالاتك وعماتك من الرضاعة،\nلأن حليمة السعدية إللي أرضعت رسول الله ﷺ وهو صغير كانت من بني سعد من هوازن.\n☆بالمناسبة صحيح\nاحنا منعرفش هل حليمة السعدية وزوجها الحارث أسلموا ولّا لأ، يعني مفيش روايات واضحة وصحيحة بتتكلم عن إسلامهم،\nلكن كلها اجتهادات العلماء،\nفي فريق قالوا إنهم أسلموا وفريق تاني متوقف في المسألة وقالوا منعرفش،\nأما بالنسبة للشيماء أخت رسول الله ﷺ ففي أحاديث بتقول إن رسول الله ﷺ قابلها بعد غزوة حنين وكانت من السَّبي فأعتقها رسول الله ﷺ وأسلمت،\nلكن كل الأحاديث إللي ذكرت القصة دي أحاديث غير صحيحة\nيعني الشيماء لم تقابل رسول الله ﷺ أصلا\nلكن هل أسلمت ولّا لأ، برده منعرفش\nوطبعا للي مهتم بعلم الحديث هتلاقوا في التعليقات\n رابط فيه تفصيل المسألة من موقع أهل الحديث، \nهتلاقوهم موضحين الأحاديث إللي جاءت فيها القصة وشارحين ليه الأحاديث دي لا تصح\nالمهم،\nالخطيب بتاع هوازن قال لرسول الله ﷺ إن لو السبايا دول كانوا وقعوا في إيد الحارث بن أبي شمر الغساني ملك الغساسنة أو في إيد النعمان بن المنذر ملك الحيرة وراحوا يطلبوا منهم إنهم يطلقوا سراح السبايا دول؛\nكانوا هيطلقوا سراحهم وهمّ مش في كرم وعطف وأخلاق رسول الله ﷺ، فمن باب أوْلى إن رسول الله ﷺ يَتفضّل عليهم ويرجّع لهم النساء والأطفال.\nرسول الله ﷺ في موقف صعب دلوقتي\nهوازن جايين ومفيش قصادهم غير الإسلام عشان يسترجعوا أي حاجة من ممتلكاتهم، \nطيب لو مسترجعوش نساؤهم وأموالهم إيه إللي هيحصل\nالغالب والمتوقع إنهم هيرتدوا عن الإسلام،\nورسول الله ﷺ عايز هوازن تسلم ومش عايزهم يرتدوا\nلكن في نفس الوقت إزاي هيرجع لهم نساءهم وأموالهم وكل الغنائم اتقسمت على الجيش وخلاص بقت ملكهم ميقدرش ياخد منها حاجة غير بإذنهم\nده غير إن رسول الله ﷺ أعطى العطايا من الخُمس عشان يتألف قلوب الناس، \nفلو أخدها منها في احتمال إنهم يرتدوا،\nفالدنيا متقفلة من كل ناحية، فإيه الحل بقى للأزمة دي\nتعالوا كده نشوف رسول الله ﷺ عمل إيه \n◇الخطوة الأولى إللي عملها رسول الله ﷺ عشان يحل المشكلة دي هي إنه حاول أنْ يصل مع هوازن إلى حل في منتصف الطريق\nبمعنى، همّ عايزين يسترجعوا كل شيء وده طبعا مستحيل،\nلكن ممكن يتنازلوا عن شيء وياخدوا شيء،\nبحيث إن ده برده ميأثرش على إسلامهم،\nفقال لهم رسول الله ﷺ في وضوح: \n《أبناؤكم ونساؤكم أحب إليكم أم أموالكم؟》\nيعني اختاروا، إما نرجع لكم أبناؤكم ونساؤكم أو نرجع لكم أموالكم،\nوفي رواية تانية بيقول:\n\"إنَّ مَعِي مَن تَرَوْنَ، وأَحَبُّ الحَديثِ إلَيَّ أصْدَقُهُ، فَاخْتَارُوا إحْدَى الطَّائِفَتَيْنِ: \nإمَّا المَالَ وإمَّا السَّبْيَ، وقدْ كُنْتُ اسْتَأْنَيْتُ بهِمْ\"\nيعني أنا مش لوحدي إللي أخدت الغنائم ده في ناس تانية كتير أخدت، فاختاروا عايزين إيه إللي يرجع لكم أكتر: الأموال ولّا النساء والأطفال،\nوقالهم إنه قعد مستنيهم حوالي من ثلاثةَ عَشرَ إلى تِسعةَ عَشرَ يوما  قبل ما يوزع الغنائم لكنهم همّ إللي اتأخروا\nوهنا رسول الله ﷺ بيحاول يلطف قلوبهم،\nيعني بيقولهم أنا كان عندي أمل إنكم هتيجوا فكنت قاعد مستنيكم عشان أرجع لكم نساءكم وأطفالكم وأموالكم،\nفهو هنا ﷺ بيتصرف بكل وضوح وبتعقل وبواقعية،\nيعني هوّ مندفعش ووعدهم بحاجة مش هيقدر يحققها لهم،\nاتكلم على إللي يقدر يحققه\nوفد هوازن لما شافوا إن رسول الله ﷺ معندوش أي مجال غير إنه يرجع لهم حاجة واحدة بس، قالوا لرسول الله ﷺ:\n\"يا رسول الله! خيّرتنا بين أموالنا وأحسابنا، فلترد إلينا نساءنا وأبناءنا، فهو أحب إلينا\"\nفاختاروا النساء والأطفال على الأموال\n☆وطبعا نتعلم من النقطة دي إننا منحطش العقدة في المنشار زي ما بنقول\nيعني لو حصلت مشكلة مش لازم يعني نطلع كسبانين منها \n %،\nيعني لو ينفع يبقى في تنازل من الطرفين عشان المشكلة تتحل فإيه المشكلة في كده؟ إيه المشكلة لما نتقابل في نص الطريق ويبقى في حل وسط\n◇الخطوة التانية بقى كانت إن رسول الله ﷺ حسّس هوازن إنه هو شخصياً معهم قلباً وقالباً، وإنه متعاطف معهم إلى أقصى درجة،\nوإنه هو شخصياً هيضحي عشانهم وهيبذل كل جهده عشان يسترد السبي من أفراد الجيش الإسلامي،\nيعني رسول الله ﷺ حط نفسه في خندق هوازن، وبقى مُدافع عن قضيتهم،\nوده لما قالهم:\n《أمّا مَا كان لي و لبَنِي عبد المطلب فهو لكم》\nيعني أنا متنازل لكم عن إللي كان من نصيبي من السبي، وبصفتي مسؤول عن عائلة عبد المطلب فأنا هطلب منهم إنهم يرجعوا السبي إللي أخذوه منكم،\nلكن في نفس الوقت أنا مقدرش أجبر باقي أفراد الجيش على رد إللي معاهم، لكني هحاول\n☆وهنا نقطة مهمة في التعامل مع الناس يا جماعة\nوهي إننا نحسس الشخص إللي بيحكيلنا مشكلته إننا حاسين بيه ومقدرين موقفه الصعب،\nونحاول نساعده باللي نقدر عليه لكن في نفس الوقت منوعدوش بحاجة احنا منقدرش عليها،\nيعني في ناس تلاقيهم خدتهم العاطفة وانفعلوا ووعدوا بحاجات مش هيقدروا ينفذوها، وبعدين يتحطوا في حرج ويضطروا ييجوا على نفسهم بعدين أو ميقدروش ينفذوا كلامهم فتحصل مشاكل أكبر،\nرسول الله ﷺ بقى معملش كده، رسول الله ﷺ كان عنده حاجة اسمها واقعية العطاء،\nيعني هو موعدش وفد هوازن باللي مش هيقدر عليه،\nهو عمل إللي يملكه فقط وتنازل عن نصيبه\n◇الخطوة الثالثة:\nإن رسول الله ﷺ اتفق مع وفد هوازن على إنهم يعملوا محاولة لطيفة كده قصاد المسلمين عشان يقنع فيها أفراد الجيش المسلم بإعادة السبي إلى هوازن،\nورسول الله ﷺ قالهم يقولوا كلمات معينة عشان يستعطفوا قلوب المسلمين،\nفقال لهم رسول الله ﷺ:\n\"إذا صليتُ الظهر بالناس فقوموا وقولوا للناس:\nإنا نستشفع برسول الله إلى المسلمين وبالمسلمين إلى رسول الله في أبنائنا ونسائنا، فسأُعطيكم عند ذلك، وأسألُ لكم\"\nيعني بيقولهم إنه بعد ما يصلي الظهر هيكلم الناس ويمهد لهم الطريق يعني،\nفلما يكلم الناس يقوموا همّ ويستشفعوا برسول الله ﷺ عشان يرجعوا لهم أبناءهم ونساءهم،\nوهنا رسول الله ﷺ هيقبل شفاعة المسلمين، ومش معقول يعني إن المسلمين مش هيقبلوا بشفاعة رسول الله ﷺ \nوهو بيأكد لهم كمان على واقعية الطلب فبينصحهم إنهم ميطلبوش الأموال والشياة، \nلكن يطلبوا السبي بس؛ عشان ميصعّبوش الأمر على المسلمين فتفشل المحاولة،\nوساعتها رسول الله ﷺ هيتدخل ويعلن قصاد الناس إنه متنازل لهم عن نصيبه ونصيب بني عبد المطلب، من باب القدوة وهيطلب من الناس بعد كده إنهم يرجعوا لهم أبناءهم ونساءهم\n☆واخدين بالكم رسول الله ﷺ بيبذل جهد كبير إزاي وبيخطط عشان خاطر قبيلة كانت بتحاربه من شهرين فقط، لأ والقبيلة دي وكانت حريصة تمام الحرص على استئصاله وأصحابه\nخطوة هائلة مذهلة، مظنش إن لها مثيل في تاريخ الأرض غير من رسول الله ﷺ\nوالأعجب بقى إن رسول الله ﷺ مش عايز يُجبر المسلمين على رأي،\nيعني هو شايف إنه لا يجوز له تأميم ما لا يملك، يعني مينفعش ياخد حاجة بوضع اليد كده وهي مش بتاعته وإن ده حق المالكين دلوقتي وهو ملوش دخل فيه،\nلكن هو هيتدخل في القضية في صورة شفيع أو وسيط يريد الخير بصدق للطرفين،\nواخدين بالكم من مَدى الرُّقي والتوازن والتعامل الحضاري\nوده مين يا جماعة\nده زعيم الأمة الإسلامية ورئيس الدولة والرسول المُطاع ﷺ\nصدقت السيدة عائشة رضي الله عنها لما قالت عن رسول الله ﷺ إنه كان قرآن يمشي على الأرض، ﷺ\nبعد ما رسول الله ﷺ صلى الظهر بالمسلمين وزي ما كان متفق مع هوازن، واتكلم مع الناس قام وفد هوازن يكلم المسلمين وكأنهم مقعدوش مع رسول الله ﷺ قبل كده ودي أول مرة يتكلموا في الموضوع،\nفقالوا زي ما رسول الله ﷺ نصحهم بالضبط:\n\"إنا نستشفع برسول الله إلى المسلمين، وبالمسلمين إلى رسول الله، في أبنائنا ونسائنا\"\nفقام رسول الله ﷺ وقال:\n\"أمّا ما كان لي ولبني عبد المطلب فهو لكم\"\nيعني كأن رسول الله ﷺ بيقول الكلام ده لأول المرة،\nفلحد كده رسول الله ﷺ عمل إللي يقدر عليه تجاه هوازن،\nومبقاش فاضل غير إن المسلمين يرجّعوا لهوازن السبي بتاعهم،\nفقام المهاجرون وقالوا:\n\"ما كان لنا فهو لرسول الله ﷺ\"\nيعني رسول الله ﷺ له مُطلق الحرية في التصرف في السبي إللي عندهم، وبالتالي رسول الله ﷺ هيرجّع السبي لهوازن،\nوقام الأنصار همّ كمان وقالوا: \n\"ما كان لنا فهو لرسول الله ﷺ\"\nوده دليل قاطع يا جماعة إن الأنصار أخدوا من أربعة أخماس الغنيمة،\nمش زي ما الفريق التاني من العلماء قالوا إنهم لم يأخذوا أي شيء من الغنائم، وإلا فهمّ هيرجّعوا إيه هنا لو مش معاهم حاجة من الغنائم \nفكده رِجِع جزء من السّبي من قسم مهم من أقسام الجيش،\nلكن اتبقى أقسام كبيرة من الجيش لسه عندهم من السبي وخاصة الأعراب؛ لأنهم غالبية الجيش، وهم في الأساس قبائل تميم وفُزَارة وسُلَيم، \nفقام الأقرع بن حابس زعيم بني تميم وقال: \nأما أنا وبنو تميم فلا\nيعني احنا مش هنرجع لكم أي حاجة،\nوقام عيينة بن حصن زعيم بني فُزارة وقال هو كمان:\nوأما أنا وبنو فزارة فلا\nوالموقف ده كده ممكن يؤثر على إسلام هوازن\nلكن رسول الله ﷺ لم ييأس، ودخل معاهم في مساومة مادية تُجارية تناسب طبيعتهم في المرحلة دي؛ \nلأن نظرتهم للموضوع كانت نظرة مادية بحتة، \nوطبعا هو لم يَلُمْهُم على أنهم لم يقبلوا شفاعته ﷺ ؛ لأن ده حقهم وهمّ رفضوا إنهم يتنازلوا عنه،\nوده مكنش أمر مباشر من رسول الله ﷺ، يعني رسول الله ﷺ مأمرهمش إنهم يتنازلوا عن السبي، هو عرَض بس إنه يرجعوا النساء والأطفال لهوازن، \nفقال لهم رسول الله ﷺ عشان يغريهم:\n\"أمّا مَن تَمسّك منكم بحقه من هذا السبي فله بكل إنسان يتنازل عنه من السبي ستُّ فرائض من أولِ شيءٍ نصيبه\"\nيعني رسول الله ﷺ بيقولهم إنهم لو تنازلوا عن السبي إللي عندهم ده هيدفع لهم قيمته مضاعف ست مرات من أول سبي يحصل عليه المسلمين بعد كده،\nفوافقت القبيلتان بالكامل على إعادة السبي إلى هوازن، ونجح عرض رسول الله ﷺ في الخروج من الأزمة، وعاد كل السبي إلى هوازن، \nإلا امرأة عجوز كانت في يد عيينة بن حصن الفزاري رفض إنه يرجعها في البداية عشان يكيد في هوازن\nوبعدين أعادها بعد كده واتحلت المشكلة.\nالعباس بن مِرْدَاس زعيم بني سليم هو كمان كان قال:\nوأما أنا وبنو سليم فلا\nلكن بنو سُلَيم نفسهم قاموا وقالوا:\nما كان لنا فهو لرسول الله ﷺ،\nيعني بنو سليم رفضوا كلام زعيمهم العباس بن مرداس وقالوا إنهم هيعيدوا السّبي مع رسول الله ﷺ،\nلكن كده مش ظاهر مين موافق ومين معترض، يعني هم قالوا كده في نفس واحد إنهم هيتنازلوا عن السبي،\nفممكن يكون في ناس منهم مش موافقين ومش ظاهرين وسط الأغلبية،\nوطبعا هنا السبي ده حق لكل فرد لازم يتنازل عنه بإرادته،\nيعني هو مش رأي أغلبية يمشي على الكل لو في اتنين أو ثلاثة معترضين،\nلأ، كل واحد فيهم لازم يكون موافق وراضي بالتنازل ده،\nفقال لهم رسول الله ﷺ:\n\" إنا لا ندري من أذِن منكم في ذلك ممن لم يأذن، فارجعوا حتى يَرفع إلينا عُرفَاؤُكم أمرَكم\"\nيعني احنا مش عارفين مين إللي موافق ومين إللي مش موافق، فانتم اتفقوا كده مع بعض وكل مجموعة يوكّلوا واحد يقول لرسول الله ﷺ الرأي النهائي،\nفعاد العُرفَاء أو النقباء بعد ما كلموا الناس، وأخبروا رسول الله ﷺ  إن الناس قد طَيبُوا وأَذِنوا، \nيعني الناس نفوسهم راضية بإنهم يرجعوا السبي، وبكده أخيرا انتهت قصة السبي والغنائم\nمتبقاش بقى غير مالك بن عوف، الزعيم إللي مجاش مع وفد هوازن،\nيا ترى هو فين ورسول الله ﷺ هيعمل معاه إيه؟\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 207, "l": "الجزء 181 | احداث السنه الثامنه من الهجرة | حاكم مكه الجديد", "u": "https://www.facebook.com/groups/710210019782034/permalink/836547347148300/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وواحد_وثمانون\n#أحداث_السنة_الثامنة_من_الهجرة\n#حاكم_مكة_الجديد\nاتكلمنا المرة إللي فاتت عن إسلام وفد وهوازن وإرجاع السبي لهم،\nوقلنا إن عوف بن مالك مع إنه كان زعيمهم وهو سبب الكارثة إللي حصلت لهم دي لكنه مجاش معاهم،\nفرسول الله ﷺ سأل وفد هوازن عنه فقالوا له إنه في الطائف في حصون ثقيف خايف على نفسه من القتل، فقال لهم رسول الله ﷺ:\n\"أخبروا مالكاً أنه إن أتاني مسلماً رددت عليه أهله وماله  وأعطيته مائة من الإبل\"\nيعني لو مالك جاء وأسلم، رسول الله ﷺ مش بس هيرجعله أهله ، ده هيرجعله أهله وماله وهيديله كمان مائة من الإبل زيادة،تخيلوا\nوده مالك بن عوف إللي جمع هوازن عشان يبيدوا المسلمين ومع ذلك رسول الله ﷺ بيتعامل معاه المعاملة دي وحريص  على إسلامه وهدايته،\nفهداية الناس لرب العالمين كانت الهدف الأسمى في حياة رسول الله ﷺ، و ده بغض النظر عن تاريخهم وعن عداوتهم السابقة له وللمسلمين، .\nوطبعا مننساش إن رسول الله ﷺ قائد حكيم بيقدر قدرات البشر وعارف إن مالك بن عوف عنده قوة لا يُستهان بها، ولا يمكن أبداً تجاهله، \nيعني رجل استطاع إنه يجمع ويحرك أكثر من (25000) ألف مقاتل، \nوعرف إنه يقنعهم إنهم يضحوا بكل ثرواتهم زي ما شوفنا عشان قضية قبائلية تافهة بالمقارنة طبعا بأهداف القتال في الإسلام، \nفإيه بقى إللي هيحصل لو انضم القائد الخطير ده إلى صفوف الجيش المسلم؟\nهيعمل إيه لو بقى مقاتل في سبيل الله بدل ما يكون مقاتل في سبيل هوازن\nفوجود شخصية خطيرة زي مالك بن عوف ده خارج الصف المسلم أمر خطير فعلاً، وخاصة إنه كان ساعتها في ثقيف، وثقيف لسه لم تُسلم،\nوخطر ثقيف لم ينقطع عن المسلمين، عشان كده رسول الله ﷺ كان حريص كل الحرص على إسلام مالك بن عوف،\nوفي نفس الوقت رسول الله ﷺ كان حريص على حِفظ كرامة مالك بن عوف،\nفرفع قيمته بإنه اختصّه بوضع خاص غير الناس، \nاختصّه بإنه هيعيد له ماله مع أهله وكمان وعده بإعطائه مائة من الإبل كنوع من تأليف القلب؛ \nلأن رسول الله ﷺ كان عارف إن إسلام هوازن ضربة كبيرة جداً لمالك بن عوف ، \nفمكنش عايز يكسر معنوياته أو يذله ويُعَيّره بانضمام جنوده لجيش المسلمين،\nولكنه عرض عليه عرض مغري جداً، وهو عارف إن وضع مالك دلوقتي بقى صعب، فهو بالعرض ده فتح له باب الرجوع إلى الله، والانضمام لدولة الإسلام\nوهي دي بقى الحكمة في أجمل صورها، مش زي ما بعض أعداء الإسلام بيقولوا عن رسول الله ﷺ إنه قدم رشوة لمالك بن عوف وإنه كده خالف ما شرعه من تحريم الرشوة\nوطبعا في فرق كبير جدا يا جماعة بين الرشوة والعطاء لتأليف القلوب،\nالرشوة دي بتُدفع من الضعيف أو المحتال لحد عنده القدرة والمكانة عشان ياخد حق مش بتاعه 《في الغالب》، \nواحنا شايفين إزاي إن رسول الله ﷺ هو القوي مش الضعيف، فإيه المصلحة الشخصية إللي رسول الله ﷺ  هياخدها من مالك بن عوف هنا غير إسلامه؟\nمفيش\nفاللي رسول الله ﷺ عمله ده كان عطاء أعطاه لمالك بن عوف عشان يتألف بيه قلبه ويدخل في الإسلام زي ما قلنا، وتأليف القلوب بالعطايا ده أصلا حاجة ربنا شرعها في الإسلام، فالموضوع بعيد كل البعد عن الرشوة\nوصل الخبر إلى مالك في الطائف، وعرف العرض المُغري إللي رسول الله ﷺ قال عليه،\nوزي ما توقع رسول الله ﷺ، وَضْع مالك بن عوف كان صعب جداً ،\nفهو كان خايف على نفسه من قبيلة ثقيف؛ لأن قبيلة ثقيف مُحاصَرين في حصون الطائف خايفين يخرجوا،\nوإللي كان سبب الأزمة إللي هم فيها دي هو مالك بن عوف،\nفبقى خايف منهم، ومالك مبقاش عنده أتباع؛ لأن قبيلته أسلمت، وبقى موقفه في غاية الحرج،\nفكانت رسالة رسول الله ﷺ هي المنقذ له من الأزمة إللي كان فيها دي، \nوبدون تردد تسلّل مالك وخرج من حصن الطائف وأسرع إلى لقاء رسول الله ﷺ وأعلن إسلامه بين يديه، ورجّع له رسول الله أهله وماله وأعطاه مائة من الإبل،\nوطبعا المعاملة دي أسرت قلب مالك بن عوف، ومين  إللي لا تأسره معاملة رسول الله ﷺ \nشوفتوا المنهج الإسلامي في التعامل مع البشر\nأي قائد غير رسول الله ﷺ من إللي مش ماشي على منهجه ﷺ بيبقى همه الأول بعد النصر البحث عن قادة عدوه عشان يحكم عليهم بالحبس، أو بالنفي، أو بالقتل، \nلكن رسول الله ﷺ كان حريص على كل البشر بغض النظر عن تاريخهم أو مواقفهم السابقة،\nفكانت نتيجة موقفه ده هو إسلام الشخصية القيادية الكبيرة مالك بن عوف،\nوبكده قوة مالك بن عوف إللي تكلمنا عنها قبل كده، وقدرته على الحشد بقت في صالح المسلمين\nلكن رسول الله ﷺ عارف إن مالك بن عوف أسلم في ظروف صعبة، \nوممكن يكون إسلامه رغبة في المال والأهل والإبل، أو عشان خايف من ثقيف أو خايق من رسول الله ﷺ ،\nفإزاي بقى نثبّت أقدامه في الإسلام، و إزاي نستفيد من طاقاته وقدراته\nشوفوا رسول الله ﷺ الحكيم عمل إيه\n◇أول حاجة :\nرسول الله ﷺ أعاد مالك بن عوف إلى زعامة هوازن؛\nلأن واحد زي مالك بن عوف مش هيقبل إنه يتهمش كده وميبقاش له لازمة،\nوالوضع مش هيبقى مستقر إلا إذا رضي القائد ده، \nوإللي في قدرات مالك مش هيرضى إلا إذا بقى هو القائد، بالإضافة إلى إن مالك بن عوف هو الأقدر على قيادة قبيلته؛ لأنه أكثر معرفة بأحوالها وبرجالها، وأدرى بشئونها وشئون المنطقة كلها،\nده غير إن مالك بن عوف كان شاب ،يعني لسه متشرّبش حب الأصنام ومضيعش عمره في الدفاع عنها،\nعشان كده رسول الله ﷺ لقى إنه من الأسلم والأفضل والأحكم إنه يعيد مالك بن عوف إلى ولاية قومه، \nوبكده يكسب مالك بن عوف ويكسب القبيلة بكاملها\n◇الحاجة التانية إللي رسول الله ﷺ عملها كانت إنه كلّف مالك بن عوف وقبيلته بمهمة في غاية الأهمية، وهي مهمة حصار قبيلة ثقيف في الطائف،\nيعني خلى مالك بن عوف هو وإللي أسلم من قبيلته يروحوا يحاصروا حصون الطائف إللي استعصت على رسول الله ﷺ، \nوبكده رسول الله ﷺ ضرب أكتر من عصفور بحجر واحد زي ما بنقول يعني\nطب إزاي بقى\n ◇أولا: \nهو كده خلى لمالك بن عوف دور إيجابي بإنه هيتحمل مسؤولية كبيرة وبالتالي ده له دور مهم في تربيته وتدريبه كقائد، \nوخلاه يحس بقيمته المهمة في الدولة الجديدة، \nوكمان حس بثقة رسول الله ﷺ فيه، والكلام ده هيثبّت أقدام مالك بن عوف وقبيلته في الدين الجديد إللي لسه داخلينه ده وكانوا بيحاربوه من شهرين بس\n◇ثانيا:\nرسول الله ﷺ سيُكفَى مئونة ثقيف.\nيعني  هيخلي قبيلة هوازن درع  للدولة الإسلامية وهي إللي هتقاتل ثقيف، \nوبكده هيقلل من قدرات وإمكانيات ثقيف، وهيقلل من خطرها على المسلمين،\nوفوق كل ده رسول الله ﷺ هيقدر دلوقتي يرجع للمدينة بأمان ويكمل مهمته في إدارة شئون الدولة الإسلامية الواسعة؛\nلأنه مكنش يقدر بأي حال من الأحوال إنه يستنى كتير في منطقة الطائف أو حنين أو مكة بعيد عن  المدينة مسافة (500) كيلو متر،\nلكن دلوقتي رسول الله ﷺ يقدر يرجع وهو مطمئن إن في حد هيسد الثغرة دي من أبناء قبيلة هوازن،\nوفعلا  كان قرار رسول الله ﷺ في منتهى الحكمة؛ لأن  مالك بن عوف رضي الله عنه وأرضاه قام بالمهمة دي على أكمل وجه، وحاصر ثقيف حصار شديد، وثقيف مقدروش يخرجوا من حصونهم،\nوقعد مالك بن عوف محاصر لحصون الطائف حوالي سنة كاملة لحد ما ثقيف فكرت في الإسلام ودخلت فيه زي ما هنشوف بعدين إن شاء الله\nبعد ما انتهت قصة هوازن وتوزيع الغنائم، قرر رسول الله ﷺ الرجوع لمكة عشان يعمل عمرة، ودي هي العمرة الثالثة لرسول الله ﷺ لحد دلوقتي واسمها عمرة الجُعْرانة،\nالأولى كانت عمرة الحديبية، والثانية كانت عمرة القضاء والثالثة هي عمرة الجعرانة، \nبعد ما رسول الله ﷺ خلص العمرة المفروض إنه هيرجع للمدينة لكن قبل ما يرجع أمر الصحابة إنهم يجمعوا دروع صفوان بن أمية إللي كان واخدها منه قبل حنين عشان يرجعها له،\nولما جمعوها لقوا بعضها مفقود، فقال رسول الله ﷺ لصفوان:\n\"إن شئتَ غَرِمْنَاها لك\"\nيعني احنا ممكن ندفعلك تمنها، فقال له صفوان رضي الله عنه:\n\"يا رسول الله، إن في قلبي اليوم من الإيمان ما لم يكن يومئذ\"\nيعني كأنه بيقوله :طبعا مش هاخد حاجة مقابل الدروع إللي ضاعت دي\nدلوقتي رسول الله ﷺ لما يمشي ويرجع للمدينة لازم يكون حد موجود يعلّم حاكم مكة الجديد وأهل مكة الإسلام،\nفترك معاهم أعلم الأمة بالحلال والحرام 《معاذ بن جبل》 رضي الله عنه،\nومعاذ بن جبل أسلم وهو عنده ثمانية عشرة سنة، وحضر بيعة العقبة الثانية،\nوحضر الغزوات كلها مع رسول الله ﷺ، ومن ساعة ما رسول الله ﷺ هاجر للمدينة ومعاذ بقى ملازم لرسول الله ﷺ، فأخذ عنه القرآن وتلقى شرائع الإسلام لحد ما بقى أَقْرَأ الصحابة لكتاب الله وأعلمهم بشرعه، \nعشان كده كان هو الشخص المناسب لمهمة تعليم أهل مكة وحاكم مكة الجديد الإسلام.\n☆مين بقى حاكم مكة الجديد ده\nفاكرين عتّاب بن أُسَيد \nإللي كان قاعد في فناء الكعبة مع أبو سفيان بن حرب والحارث بن هشام، وكانوا بيسمعوا بلال وهو بيأذن، \nفقال عتّاب بن أُسيد ساعتها وهو مشرك:\n\"أكرم الله أسيداً ألاّ يكونَ سمع هذا فسمع منه ما يغيظه، ما وَجدَ محمد غير هذا الغراب الأسود مؤذناً\"\nوبعدين لما عدى عليهم رسول الله ﷺ قال لهم الكلام إللي قالوه وأسلم عتاب بن أسيد و الحارث بن هشام ساعتها،\nفحاكم الجديد بدل أبو سفيان هو عتّاب بن أسيد ده\nفبعد ما أسلم عتّاب خلاه رسول الله ﷺ حاكم مكة بدل أبو سفيان، يعني لما رسول الله ﷺ خرج لغزوة حنين كان إللي بيحكم مكة ساعتها هو عتّاب بن أسيد،\nوزي ما احنا عارفين رسول الله ﷺ مش بيختار أي حد كده وخلاص، \nفهو اختار عتاب بن أسيد بالذات لأنه كان من بني أمية وهي نفس قبيلة أبي سفيان، \nفلو رسول الله ﷺ أعطى الإمارة لحد تاني غير أبو سفيان ممكن ساعتها أبو سفيان يحزن ويتضايق من كده و يثور، \nوممكن تثور معاه بنو أمية وخصوصا إنه ساعتها كان لسه مسلم جديد، \nوالكلام ده كان بعد فتح مكة مباشرة، فرسول الله ﷺ مكنش عايز يحصل قلق واضطرابات في مكة عالفاضي وأهل مكة كانوا لسه داخلين الإسلام من كم يوم بس،\nفلما بنو أمية يشوفوا إن إمارة مكة لسه فيهم هيبقى ده فيه تأليف لقلوبهم وكمان مش هيعملوا مشاكل لما أبو سفيان يتشال من زعامة مكة؛ لأن عتاب بن أسيد منهم\nفكان أنسب حل إنه يعطي إمارة مكة لعتاب بن أسيد\nوطبعا مش معنى كده يا جماعة إن عتاب مكنش عنده الإمكانيات إللي تؤهله إنه يحكم مكة، وإنه اتعين كده عشان قبيلته\nاحنا بنتكلم هنا عن رسول الله ﷺ، هو مش هيختار أي شخصية كده وخلاص\nفعتاب كان شاب عمره حوالي عشرين سنة، قلبه مكنش لسه تلوث كثيرا بعقائد المشركين،\nومكنش في تاريخ عداء طويل بينه وبين المسلمين زي أبو سفيان مثلا،\nفهيبقى سهل إنه ينقاد لرسول الله ﷺ ويسمع كلامه،\nوفعلا عتاب حَسُن إسلامه جدا وكان كثير الصلاة والصيام والصدقة، \nوكان من المقربين جداً إلى رسول الله ﷺ، وترك رسول الله ﷺ معاه معاذ بن جبل عشان يعلمه أمور الإسلام ورجع رسول الله ﷺ مع المهاجرين والأنصار إلى المدينة.\n☆ممكن حد يسأل ويقول : طيب ليه رسول الله ﷺ مسابش أبا سفيان على حكم مكة؟\nما هو خلى مالك بن عوف زعيم للي أسلموا من هوازن، وهو كان زعيمهم قبل ما يسلموا زي أبو سفيان كده\nشوفوا، \nأبو سفيان كان هو زعيم مكة من بعد مقتل أبي جهل على طول، يعني هو له تاريخ طويل جداً من العداء مع المسلمين، وعنده ميراث ضخم من الكراهية لرسول الله ﷺ، \nورسول الله ﷺ مكنش لسه مطمئن لإسلام أبي سفيان عشان يعطيه إمارة مكة،\nوخصوصا إن مكة هي أعظم مدن العرب على الإطلاق، فهو  ميقدرش يعطيها لرجل لسه لم يثق في إسلامه، \nواحنا شوفنا في الحوار إللي حصل بين رسول الله ﷺ وبين أبي سفيان قبل فتح مكة إزاي أبو سفيان لحد اللحظات الأخيرة مكنش لسه مقتنع تمام الاقتناع بقضية النبوة وكان أسلم مضطر، \nبعكس مالك بن عوف إللي كان لسه حديث العهد بالعداوة مع رسول الله ﷺ، \nوكل تاريخ العلاقة بينه وبين رسول الله ﷺ لا يتعدى الأيام إللي حصلت فيها غزوة حنين،\nوأبو سفيان كان كبير في السن وغرق لسنوات طويلة في عبادة الأصنام لحد ما قلبه تشربها،\nبعكس مالك بن عوف إللي قلنا عنه من شوية إنه كان شاب حديث السن لم يفنِ عمره في حب الأصنام،\nومننساش نقطة مهمة جدا وهي إن أبا سفيان كان يقود أكثر من قبيلة في مكة حاربت رسول الله ﷺ لسنوات طويلة وممكن تنقلب عليه في أي لحظة، \nبعكس مالك بن عوف إللي كان يقود قبيلة تشعر بالجميل، وتعترف بالفضل لرسول الله ﷺ إللي أعاد لهم السبي بالأسلوب الرائع إللي شوفناه،\nفالوضع مختلف تماما بين مالك بن عوف وبين أبو سفيان\nرجع رسول الله ﷺ إلى المدينة في آواخر ذو القعدة، وقبل ما نعرف الأحداث إللي حصلت في المدينة هنتكلم عن ثلاث سرايا كانوا حصلوا بعد فتح مكة مباشرة في المناطق المحيطة بمكة،\nواحدة بقيادة خالد ين الوليد، والتانية بقيادة قَيْس بن سعد بن عبادة والثالثة بقيادة الطُّفيل بن عمرو الدوسي،\nوهنعرف تفاصيل السرايا دي المرة الجاية إن شاء الله"}]);
